import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  servedBy, servedByUpdates, servedByBaselining, withMechanism,
  MECHANISMS, DEFAULT_MECHANISM, MAINTENANCE, MECHANISM_KEY,
} from '../engine/served-by.mjs';

// The skew guard (#768's first risk): while both mechanisms exist, exactly one
// serves a repo. These are the cases that decide which — including the ones where
// the honest answer is "the repo did not say".

test('a repo that says nothing keeps doing what it does today', () => {
  assert.deepEqual(servedBy(undefined), { mechanism: 'baselining', declared: false });
  assert.deepEqual(servedBy({}), { mechanism: 'baselining', declared: false });
  assert.deepEqual(servedBy({ [MAINTENANCE]: {} }), { mechanism: 'baselining', declared: false });
  assert.equal(DEFAULT_MECHANISM, 'baselining', 'the default points at what is already true, never at the new thing');
});

test('a declared mechanism is taken, and reported as declared', () => {
  for (const m of MECHANISMS) {
    assert.deepEqual(servedBy({ [MAINTENANCE]: { [MECHANISM_KEY]: m } }), { mechanism: m, declared: true });
  }
});

test('an unrecognised value is undeclared and carries what it said — never a silent default', () => {
  // The one case where guessing could hand a repo to the wrong mechanism. It reads as
  // "not declared" so a caller that cares can stop, and it keeps the offending value
  // so the report can name it.
  const r = servedBy({ [MAINTENANCE]: { [MECHANISM_KEY]: 'both' } });
  assert.equal(r.declared, false);
  assert.equal(r.invalid, 'both');
  assert.equal(r.mechanism, DEFAULT_MECHANISM, 'and it falls back to the status quo, not the new flow');
  assert.equal(servedBy({ [MAINTENANCE]: { [MECHANISM_KEY]: 7 } }).invalid, 7);
});

test('exactly one mechanism serves a repo, whatever the declaration says', () => {
  // The property the whole flag exists for, asserted over every shape above rather
  // than trusted to two predicates that could drift apart.
  const shapes = [
    undefined, {}, { [MAINTENANCE]: {} },
    { [MAINTENANCE]: { [MECHANISM_KEY]: 'updates' } },
    { [MAINTENANCE]: { [MECHANISM_KEY]: 'baselining' } },
    { [MAINTENANCE]: { [MECHANISM_KEY]: 'nonsense' } },
    { [MAINTENANCE]: { delivery: 'auto-merge' } },
  ];
  for (const s of shapes) {
    assert.notEqual(servedByUpdates(s), servedByBaselining(s), JSON.stringify(s));
  }
});

test('the flip writes the mechanism explicitly and touches nothing else', () => {
  const before = { packs: ['basics'], [MAINTENANCE]: { delivery: 'auto-merge' }, claudinite: { engineVersion: 2 } };
  const after = withMechanism(before, 'updates');
  assert.equal(after[MAINTENANCE][MECHANISM_KEY], 'updates');
  assert.equal(after[MAINTENANCE].delivery, 'auto-merge', 'the sibling setting survives');
  assert.deepEqual(after.packs, ['basics']);
  assert.deepEqual(after.claudinite, { engineVersion: 2 });
  assert.equal(before[MAINTENANCE][MECHANISM_KEY], undefined, 'and the input is not mutated');
  // Declared, and now readable as such — which is what makes the inferred case above
  // a piece of drift an update can repair rather than a state code interprets forever.
  assert.deepEqual(servedBy(after), { mechanism: 'updates', declared: true });
});

test('the flip refuses a mechanism that does not exist', () => {
  assert.throws(() => withMechanism({}, 'whatever'), /unknown mechanism/);
});

// basics task: update — the versioned engine/pack update flows, run by a repo on
// itself (#768, docs/versioned-updates/DESIGN.md). The successor to `baselining`,
// and for now its sibling: exactly one of the two serves any repo, decided by that
// repo's own `maintenance.mechanism` (engine/served-by.mjs).
//
// A repo that has not been flipped declares nothing, is served by baselining, and
// never reaches this task's worker — which stands down in that case rather than
// assuming. So adding this task changes nothing for a member until someone writes
// the flag into its declaration.
//
// Two stages, like baselining's. The DETERMINISTIC flows are `prework`
// (worker.mjs): they converge the mount, run the version-ranged migrations, gate on
// the converged tree's self-test, open the PR, and act on the terminal. The AGENT
// stage runs only when the pack flow's apply stage is needed — the pack's new rules
// meeting member-authored content the canon has never seen.
//
// Self-contained (imports nothing) so the scheduler, executor, and a human all load
// it standalone — the whole contract lives in this default export.

const OVERDUE_DAYS = 1;

export default {
  id: 'update',
  frequency: 'daily-2h',                 // the same 02:00 slot baselining holds: a repo's mount is converged before anything reads it
  precondition_signals: ['stamp', 'sharedMount'],
  agent_model: 'sonnet',                 // the apply stage only — most runs are agentless
  expected_outcome: 'merged-pr',
  agent_instructions: 'task.md',

  prework: 'node worker.mjs',
  prework_timeout: 900,
  agent_execution_timeout: 1800,

  // PURE over the collected signals. It gates only that the worker RUNS; the worker
  // owns every decision after that, including whether this repo is its to serve —
  // which is deliberately NOT decided here. The signals carry the stamp, not the
  // declaration, and a precondition that guessed at the mechanism from a stamp would
  // be a second answer to a question `servedBy` already answers from the file.
  precondition(signals) {
    const stamp = signals.stamp ?? {};
    if (!stamp.ref && stamp.ageDays === null) {
      return { run: false, reason: 'no vendored mount (no stamp) — nothing to update' };
    }
    const age = stamp.ageDays;
    if (age !== null && age < OVERDUE_DAYS && !(signals.sharedMount?.changedPacks ?? []).length) {
      return { run: false, reason: `converged ${age}d ago and no pack moved — nothing due` };
    }
    return {
      run: true,
      reason: 'the mount is due an update pass',
      context: [
        'The deterministic flows have already run: the mount is converged, the version-ranged migrations applied, and the update PR is open.',
        'Your job is only the apply stage — bring this repo\'s own content in line with the updated pack rules on that branch, and verify the executor routine. Do not re-run the mechanical converge.',
      ],
    };
  },
};

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, existsSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { updateBranchName, updatePullText, main } from '../../packs/basics/tasks/update/worker.mjs';
import { NEEDS_HUMAN } from '../../updates/engine-update.mjs';

// The update runner's git-free surface. Its clone/push/PR half is validated by the
// live pilot, exactly as baselining's is — what is unit-testable is the naming, the
// text a human reads when a run stops, and the stand-down that decides whether any
// of it happens at all.

test('a branch carries its date and a seed, so two runs on one day cannot collide', () => {
  const a = updateBranchName('2026-08-12', 'abc123');
  const b = updateBranchName('2026-08-12', 'def456');
  assert.equal(a, 'claudinite/update-2026-08-12-abc123');
  assert.notEqual(a, b);
  assert.match(a, /2026-08-12/, 'a name a human can read a week later');
});

test('the PR text leads with the terminal, then what moved', () => {
  const { title, body } = updatePullText(
    { action: 'needs-human', why: 'the converged tree FAILED its self-test' },
    { engine: { from: 1, to: 2 }, packs: { plan: [{ id: 'basics', from: 1, to: 2 }, { id: 'sheepdog', from: 3, to: 3 }] } },
  );
  assert.match(title, /engine 1 → 2/);
  assert.match(title, /basics 1 → 2/);
  assert.ok(!title.includes('sheepdog'), 'a pack that did not move is not news');
  assert.match(body.split('\n')[0], /needs-human/, 'the first line says which terminal fired');
  assert.match(body, /FAILED its self-test/);
  assert.match(body, /stays open/);
});

test('the PR text says plainly when nothing moved', () => {
  const { title, body } = updatePullText({ action: 'merge', why: 'green' }, { engine: { from: 2, to: 2 }, packs: { plan: [] } });
  assert.equal(title, 'Claudinite update');
  assert.match(body, /No version moved/);
});

test('an unstamped repo reads as unstamped, not as version zero', () => {
  const { title } = updatePullText({ action: 'merge', why: 'green' }, { engine: { from: null, to: 2 }, packs: { plan: [] } });
  assert.match(title, /engine unstamped → 2/);
});

test('the apply-stage body says the merge waits on the repair', () => {
  const { body } = updatePullText({ action: 'apply-stage', why: 'rules met member content' }, { engine: { from: 2, to: 2 }, packs: { plan: [] } });
  assert.match(body, /before anything merges/);
});

test('the runner stands down for a repo baselining serves', async () => {
  // The other half of the skew guard, at the only place it can be wrong. Driven
  // through the real main() against a real directory, because what matters is that
  // it stands down BEFORE the clone — a stubbed clone would prove nothing about it.
  const root = mkdtempSync(join(tmpdir(), 'claudinite-updskew-'));
  try {
    writeFileSync(join(root, '.claudinite-checks.json'), `${JSON.stringify({
      packs: ['basics'],
      maintenance: { delivery: 'auto-merge' },     // no mechanism → baselining, the status quo
      claudinite: { updated: '2026-08-12T00:00:00Z', ref: 'abc123' },
    }, null, 2)}\n`);

    const said = [];
    const log = console.log;
    const env = { ...process.env };
    process.env.CLAUDINITE_REPO_ROOT = root;
    process.env.CLAUDINITE_REPO = 'o/r';
    process.env.GITHUB_TOKEN = 'not-used-because-it-stands-down-first';
    console.log = (...a) => said.push(a.join(' '));
    try { await main(); } finally { console.log = log; process.env = env; }

    assert.match(said.join('\n'), /served by baselining — standing down/);
    assert.ok(!existsSync(join(root, '.git')), 'no branch, no clone, no write');
  } finally { rmSync(root, { recursive: true, force: true }); }
});

test('the terminal vocabulary the runner acts on is the flows\' own', async () => {
  // A drift guard across the seam: the runner branches on `terminal.action`, and the
  // strings it branches on have to be the ones terminals.mjs can actually produce.
  const { TERMINALS } = await import('../../updates/terminals.mjs');
  const src = await import('node:fs').then((fs) => fs.readFileSync('packs/basics/tasks/update/worker.mjs', 'utf8'));
  for (const action of ['merge', 'needs-human', 'apply-stage']) {
    assert.ok(TERMINALS.includes(action), `${action} is not a terminal the flows produce`);
    assert.ok(src.includes(`'${action}'`), `the runner never handles the ${action} terminal`);
  }
  assert.equal(NEEDS_HUMAN, 'needs-human', 'the label and the terminal are one string');
});

// THE UPDATE RUNNER (#768) — the shell that makes the versioned flows actually run
// against a member. Everything it decides was decided elsewhere: the flows judge and
// write, `terminalFor` says what happens to the PR, `servedBy` says whether this repo
// is ours at all. What lives here is the I/O none of them may carry — the clone, the
// branch, the commit, the push, the PR, and the hand-off.
//
// SAME SHAPE AS BASELINING, deliberately. That worker is the proven pattern for
// "converge a member from its own Actions run": clone canon fresh, run the CLONE's
// scripts as subprocesses rather than the mount's stale copies, deliver on a branch,
// and let the shared landing helper own every nuance of arming versus merging. A
// second, cleverer shape here would be a second set of the same bugs.
//
// IT STANDS DOWN unless the repo declares itself served by the update flows. The
// inverse of baselining's guard, from the same definition, so exactly one mechanism
// converges a mount — and a repo that has said nothing is not this one's to touch.
import { execFileSync } from 'node:child_process';
import { readFileSync, existsSync, mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { pathToFileURL } from 'node:url';
import { servedBy } from '../../../../engine/served-by.mjs';
import { resolveDelivery, pullCreateError, landDelivery } from '../../../../engine/scheduler/land-pr.mjs';

const CANON_URL = 'https://github.com/missingbulb/Claudinite.git'; // public — no token
const UPDATE_PREFIX = 'claudinite/update';
const API = 'https://api.github.com';

const git = (args, opts = {}) =>
  execFileSync('git', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], ...opts });

async function gh(token, path, { method = 'GET', body } = {}) {
  const res = await fetch(`${API}${path}`, {
    method,
    headers: {
      authorization: `Bearer ${token}`,
      accept: 'application/vnd.github+json',
      'x-github-api-version': '2022-11-28',
      ...(body ? { 'content-type': 'application/json' } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  let json = null;
  try { json = await res.json(); } catch { /* empty body */ }
  return { status: res.status, json };
}

// --- pure helpers (exported, unit-tested git-free) --------------------------

// One branch per run, dated and seeded like baselining's: two runs on one day must
// not collide, and a name that carries its date is one a human can read a week later.
export const updateBranchName = (day, seed) => `${UPDATE_PREFIX}-${day}-${seed}`;

// The PR title and body for a terminal. The body is what a human reads when the run
// stopped, so it says WHICH terminal fired and why in its first line — a PR that only
// says "an update ran" makes every reader re-derive the thing the run already knew.
export function updatePullText(terminal, { engine, packs }) {
  const moved = [
    ...(engine?.from !== engine?.to ? [`engine ${engine?.from ?? 'unstamped'} → ${engine?.to}`] : []),
    ...(packs?.plan ?? []).filter((p) => p.from !== p.to).map((p) => `${p.id} ${p.from ?? 'unstamped'} → ${p.to}`),
  ];
  const title = moved.length ? `Claudinite update: ${moved.join(', ')}` : 'Claudinite update';
  const lines = [`**${terminal.action}** — ${terminal.why}`, ''];
  if (moved.length) lines.push('Versions moved by this run:', ...moved.map((m) => `- ${m}`), '');
  else lines.push('No version moved; this run converged the mount and changed nothing else.', '');
  if (terminal.action === 'needs-human') {
    lines.push('This PR stays open. Nothing merges on a non-green terminal — see the label.');
  } else if (terminal.action === 'apply-stage') {
    lines.push('The deterministic half is done. The agent stage applies the new rules to this repo\'s own content before anything merges.');
  }
  return { title, body: `${lines.join('\n')}\n` };
}

// --- I/O shell (validated by the live pilot, not unit tests) ----------------

export async function main() {
  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
  const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
  const base = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
  const token = process.env.GITHUB_TOKEN;
  const requestFile = process.env.CLAUDINITE_REQUEST_AGENT;
  if (!repo) { console.error('update: no repo (CLAUDINITE_REPO/GITHUB_REPOSITORY)'); process.exit(1); }
  if (!token) { console.error('update: no GITHUB_TOKEN in env'); process.exit(1); }

  const checksPath = join(root, '.claudinite-checks.json');
  if (!existsSync(checksPath)) { console.log('update: no .claudinite-checks.json — nothing to update'); return; }
  const declaration = JSON.parse(readFileSync(checksPath, 'utf8'));

  const served = servedBy(declaration);
  if (served.mechanism !== 'updates') {
    console.log(`update: this repo is served by ${served.mechanism} — standing down`);
    return;
  }
  const { delivery } = resolveDelivery(declaration?.maintenance?.delivery);
  if (!delivery) {
    console.error(`update: maintenance.delivery "${declaration?.maintenance?.delivery}" is neither auto-merge nor review`);
    process.exit(1);
  }

  // The flows run from a FRESH CANON CLONE, never from this repo's mount: the mount is
  // the thing being replaced, and a flow executing its own stale copy is how a broken
  // update makes itself permanent (baselining's worker takes the same care).
  const tmp = mkdtempSync(join(tmpdir(), 'claudinite-canon-'));
  try {
    git(['clone', '--depth', '1', CANON_URL, tmp]);
    const load = async (rel) => import(pathToFileURL(join(tmp, rel)).href);
    const { engineUpdate } = await load('updates/engine-update.mjs');
    const { packUpdate } = await load('updates/pack-update.mjs');
    const { terminalFor, applyStageBrief } = await load('updates/terminals.mjs');

    // ENGINE FIRST, always: a pack declares the minimum engine it runs on, and the
    // pack flow enforces that against what this repo HAS. Running packs first would
    // check every pack against yesterday's engine and block updates that the very
    // next step would have made legal.
    const engine = await engineUpdate(root, { fullName: repo, delivery, selfTestRun: undefined });
    console.log(`update: engine — ${engine.status}: ${engine.detail}`);
    let packs = null;
    if (engine.status !== 'needs-human') {
      packs = await packUpdate(root, { fullName: repo, delivery, selfTestRun: undefined });
      console.log(`update: packs — ${packs.status}: ${packs.detail}`);
    }

    // The engine's terminal wins when it stopped the run: nothing downstream of a
    // refused engine update is trustworthy, including a pack flow that never ran.
    const outcome = engine.status === 'needs-human' ? engine : packs;
    const terminal = terminalFor(outcome);

    const changed = git(['-C', root, 'status', '--porcelain']).trim();
    if (!changed && terminal.action !== 'needs-human') {
      console.log('update: nothing changed — no branch, no PR');
      return;
    }

    const day = new Date().toISOString().slice(0, 10);
    const seed = Math.random().toString(36).slice(2, 8);
    const branch = updateBranchName(day, seed);
    git(['-C', root, 'checkout', '-B', branch]);
    git(['-C', root, 'add', '-A']);
    const staged = git(['-C', root, 'diff', '--cached', '--name-only']).split('\n').filter(Boolean);
    const { title, body } = updatePullText(terminal, { engine, packs });
    git(['-C', root, '-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
      'commit', ...(staged.length ? [] : ['--allow-empty']), '-m', title]);
    git(['-C', root, 'push', '--force', `https://x-access-token:${token}@github.com/${repo}.git`, `HEAD:refs/heads/${branch}`]);

    const created = await gh(token, `/repos/${repo}/pulls`, { method: 'POST', body: { head: branch, base, title, body } });
    const failure = pullCreateError(created.status, created.json);
    if (failure) throw new Error(`could not open the update PR for ${branch}: ${failure}`);
    const pr = created.json;
    console.log(`update: opened PR #${pr.number} on ${branch} (${terminal.action})`);

    // The terminal, acted on. Only one action merges, and it is the one the flow
    // already judged green — everything else leaves the PR standing, labelled or
    // handed to the agent stage.
    if (terminal.action === 'merge') {
      await landDelivery({ token, repo, base, pr, delivery });
    } else if (terminal.action === 'needs-human') {
      await gh(token, `/repos/${repo}/issues/${pr.number}/labels`, { method: 'POST', body: { labels: [terminal.label] } });
      console.log(`update: left PR #${pr.number} open and labelled ${terminal.label} — ${terminal.why}`);
    } else if (terminal.action === 'apply-stage' && requestFile) {
      writeFileSync(requestFile, `${JSON.stringify({
        marker: 'agent-requested',
        delivered: { branch, pr: pr.number, merged: false },
        reason: { code: 'apply-stage', detail: terminal.why },
        brief: applyStageBrief({ packs: terminal.packs, branch }),
      })}\n`);
      console.log(`update: requested the apply stage for ${terminal.packs.join(', ')}`);
    }
  } finally {
    rmSync(tmp, { recursive: true, force: true });
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((e) => { console.error(`update failed: ${e.message}`); process.exit(1); });
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, existsSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { engineUpdate, engineRecordsInGap, isEngineFile, NEEDS_HUMAN, deliveryDecision, runSelfTest } from '../updates/engine-update.mjs';
import { ENGINE_VERSION } from '../engine/version.mjs';
import { applyVendor } from '../vendoring/apply-vendor-set.mjs';
import { SCHEDULER_WORKFLOW } from '../engine/scheduler/converge-wiring.mjs';

// The engine update flow, driven against REAL member trees built by the real vendor
// writer — the thing a member actually holds. A fixture corpus would prove the
// sequencing and say nothing about whether this canon's own engine can be laid down
// on a repo, which is the only question a member has.
const ROOT = dirname(dirname(fileURLToPath(import.meta.url)));
const MOUNT = join('.claudinite', 'shared');

function makeMember(declaration = { packs: ['basics'] }) {
  const root = mkdtempSync(join(tmpdir(), 'claudinite-member-'));
  writeFileSync(join(root, '.claudinite-checks.json'), `${JSON.stringify(declaration, null, 2)}\n`);
  mkdirSync(join(root, 'src'), { recursive: true });
  writeFileSync(join(root, 'src', 'app.js'), 'project code\n');
  return root;
}

const stampOf = (root) => JSON.parse(readFileSync(join(root, '.claudinite-checks.json'), 'utf8')).claudinite;
const setStamp = (root, patch) => {
  const p = join(root, '.claudinite-checks.json');
  const raw = JSON.parse(readFileSync(p, 'utf8'));
  raw.claudinite = { ...(raw.claudinite ?? {}), ...patch };
  writeFileSync(p, `${JSON.stringify(raw, null, 2)}\n`);
};

test('the engine half is the engine tree plus the catalog nothing else owns', () => {
  assert.equal(isEngineFile('engine/selftest.mjs'), true);
  assert.equal(isEngineFile('packs/directory.GENERATED.md'), true, 'the catalog ships with every mount, so no pack owns it');
  assert.equal(isEngineFile('packs/basics/RULES.md'), false);
  assert.equal(isEngineFile('packs/sheepdog/migrations/2026-08-11-x/migration.mjs'), false, 'a pack\'s records are the pack flow\'s');
});

test('the gap is engine records only, and empties as the repo catches up', () => {
  const behind = engineRecordsInGap({ engineVersion: 0 });
  assert.ok(behind.length > 0, 'a repo below version 1 needs the records that landed at it');
  assert.ok(behind.every((d) => d.startsWith('engine/migrations/')), `a pack record leaked into the engine gap: ${behind}`);
  assert.deepEqual(engineRecordsInGap({ engineVersion: ENGINE_VERSION }), [], 'an up-to-date repo needs none');
});

test('a repo that never adopted is a needs-human terminal, not a crash', async () => {
  const root = mkdtempSync(join(tmpdir(), 'claudinite-bare-'));
  const r = await engineUpdate(root, { fullName: 'o/r' });
  assert.equal(r.status, NEEDS_HUMAN);
  assert.match(r.detail, /never adopted/);
  rmSync(root, { recursive: true, force: true });
});

test('malformed settings stop the run before anything is written', async () => {
  const root = makeMember();
  writeFileSync(join(root, '.claudinite-checks.json'), '{ not json\n');
  const r = await engineUpdate(root, { fullName: 'o/r' });
  assert.equal(r.status, NEEDS_HUMAN);
  assert.ok(!existsSync(join(root, MOUNT)), 'a refused update writes nothing at all');
  rmSync(root, { recursive: true, force: true });
});

test('a repo far behind is now servable end to end — the notes that blocked it are gone', () => {
  // This test used to assert the OPPOSITE: two engine records carried agentic notes,
  // so the flow refused any repo whose gap contained them, and a repo at version 0
  // could not be served at all. Retiring the last of those notes (#768 Phase 4) is
  // what changed, and the registry now REJECTS an engine record carrying one, so the
  // refusal can no longer be reached through a real record — it is enforced a level
  // earlier, where it cannot be written in the first place.
  //
  // What is left to assert here is the consequence: the gap of a badly-lagging repo
  // is now runnable, which is the whole thing the retirement bought.
  const behind = engineRecordsInGap({ engineVersion: 0 });
  assert.ok(behind.length > 0, 'a repo at version 0 still has records to run');
  assert.ok(behind.every((d) => d.startsWith('engine/migrations/')), behind.join(', '));
});

test('a real member is converged onto this canon\'s engine, and stamped for it', async () => {
  const root = makeMember();
  assert.deepEqual((await applyVendor(root)).errors, []);
  // Something the new engine must overwrite, and something stale it must remove.
  writeFileSync(join(root, MOUNT, 'engine', 'selftest.mjs'), 'locally mangled\n');
  writeFileSync(join(root, MOUNT, 'engine', 'zzz-stale.mjs'), 'from an engine that no longer exists\n');

  const r = await engineUpdate(root, { fullName: 'o/r' });
  assert.equal(r.status, 'ok', r.detail);
  assert.equal(r.to, ENGINE_VERSION);

  assert.equal(
    readFileSync(join(root, MOUNT, 'engine', 'selftest.mjs'), 'utf8'),
    readFileSync(join(ROOT, 'engine', 'selftest.mjs'), 'utf8'),
    'the engine is replaced wholesale, so local drift reverts');
  assert.ok(!existsSync(join(root, MOUNT, 'engine', 'zzz-stale.mjs')), 'a file the new engine dropped must not survive');
  assert.equal(stampOf(root).engineVersion, ENGINE_VERSION);
  assert.equal(readFileSync(join(root, 'src', 'app.js'), 'utf8'), 'project code\n', 'the repo\'s own files are untouched');
  rmSync(root, { recursive: true, force: true });
});

test('the flow never writes a workflow file — the one thing its credential cannot deliver', async () => {
  const root = makeMember();
  assert.deepEqual((await applyVendor(root)).errors, []);
  rmSync(join(root, '.github'), { recursive: true, force: true });

  const r = await engineUpdate(root, { fullName: 'o/r' });
  assert.equal(r.status, 'ok', r.detail);
  assert.ok(!existsSync(join(root, SCHEDULER_WORKFLOW)),
    'the engine flow must leave .github/workflows/ to the pack flow — writing one fails the whole push');
  assert.ok(!r.wiring.includes(SCHEDULER_WORKFLOW));
  // …while the wiring it MAY converge still happened.
  assert.ok(existsSync(join(root, '.claude', 'settings.json')), 'hooks are wiring this flow owns');
  rmSync(root, { recursive: true, force: true });
});

test('the packs half of the mount is left alone — it belongs to the pack flow', async () => {
  const root = makeMember();
  assert.deepEqual((await applyVendor(root)).errors, []);
  const packFile = join(root, MOUNT, 'packs', 'basics', 'RULES.md');
  writeFileSync(packFile, 'a pack version this flow has no business replacing\n');

  assert.equal((await engineUpdate(root, { fullName: 'o/r' })).status, 'ok');
  assert.equal(readFileSync(packFile, 'utf8'), 'a pack version this flow has no business replacing\n');
  rmSync(root, { recursive: true, force: true });
});

test('an up-to-date repo is a clean no-gap run, not a special case', async () => {
  const root = makeMember();
  assert.deepEqual((await applyVendor(root)).errors, []);
  const r = await engineUpdate(root, { fullName: 'o/r' });
  assert.equal(r.status, 'ok');
  assert.deepEqual(r.records, [], 'nothing above what it has installed');
  assert.equal(stampOf(root).engineVersion, ENGINE_VERSION);
  rmSync(root, { recursive: true, force: true });
});

test('dry run judges everything and writes nothing', async () => {
  const root = makeMember();
  assert.deepEqual((await applyVendor(root)).errors, []);
  writeFileSync(join(root, MOUNT, 'engine', 'selftest.mjs'), 'mangled\n');

  const r = await engineUpdate(root, { fullName: 'o/r', dryRun: true });
  assert.equal(r.status, 'ok');
  assert.equal(r.dryRun, true);
  assert.ok(r.files > 0, 'it reports what it would lay down');
  assert.equal(readFileSync(join(root, MOUNT, 'engine', 'selftest.mjs'), 'utf8'), 'mangled\n', 'and changed nothing');
  rmSync(root, { recursive: true, force: true });
});

// --- the self-test gate and its override (#768 Phase 1) -----------------------

test('the gate decides by the self-test, and every non-green end looks the same', () => {
  assert.deepEqual(deliveryDecision({ selftestOk: true }).action, 'merge');
  // A repo that reviews its own PRs is not overridden by a green gate.
  assert.equal(deliveryDecision({ selftestOk: true, delivery: 'review' }).action, 'keep');

  const red = deliveryDecision({ selftestOk: false });
  assert.equal(red.action, 'needs-human');
  assert.equal(red.label, NEEDS_HUMAN);
  assert.match(red.why, /FAILED its self-test/);
  // Red is red whatever the repo's delivery preference says.
  assert.equal(deliveryDecision({ selftestOk: false, delivery: 'review' }).action, 'needs-human');
});

test('force-merge-on-red-ci is per-invocation, and leaves a trace when used', () => {
  const forced = deliveryDecision({ selftestOk: false, forceMergeOnRedCi: true });
  assert.equal(forced.action, 'merge');
  assert.equal(forced.forced, true, 'an override that leaves no trace is indistinguishable from a gate that passed');
  assert.match(forced.why, /force-merge-on-red-ci/);
  // Absent, the default is the gate — never the override.
  assert.equal(deliveryDecision({ selftestOk: false }).action, 'needs-human');
});

test('the override is never read from the repo — a stored default is not an override', async () => {
  // The whole point of "per-invocation, never a stored default": one operator's
  // judgment about one release must not become standing policy nobody remembers
  // granting. A declaration that asks for it is simply not consulted.
  const root = makeMember({ packs: ['basics'], forceMergeOnRedCi: true, claudinite: { forceMergeOnRedCi: true } });
  assert.deepEqual((await applyVendor(root)).errors, []);
  const r = await engineUpdate(root, { fullName: 'o/r', selfTestRun: () => { throw new Error('mount is broken'); } });
  assert.equal(r.status, NEEDS_HUMAN, 'the declaration asked to force a merge and was ignored');
  assert.equal(r.decision.action, 'needs-human');
  rmSync(root, { recursive: true, force: true });
});

test('a converged tree that fails its self-test ends at needs-human, with the update still applied', async () => {
  // The update itself is not rolled back: the mount is converged and stamped, and
  // what the gate decides is whether that lands on main — the PR stays open instead.
  const root = makeMember();
  assert.deepEqual((await applyVendor(root)).errors, []);
  const r = await engineUpdate(root, { fullName: 'o/r', selfTestRun: () => { const e = new Error('x'); e.stdout = 'selftest: 1 of 5 probes FAILED'; throw e; } });
  assert.equal(r.status, NEEDS_HUMAN);
  assert.equal(r.selftest.ok, false);
  assert.match(r.selftest.output, /probes FAILED/);
  assert.equal(stampOf(root).engineVersion, ENGINE_VERSION, 'the converge happened; the gate governs the merge');
  rmSync(root, { recursive: true, force: true });
});

test('the gate runs the MOUNT\'s self-test, not the canon\'s', async () => {
  const root = makeMember();
  assert.deepEqual((await applyVendor(root)).errors, []);
  const seen = [];
  await engineUpdate(root, { fullName: 'o/r', selfTestRun: (st, r) => { seen.push(st); return 'ok'; } });
  assert.ok(seen[0].startsWith(join(root, MOUNT)), `${seen[0]} is not inside the member's own mount`);
});

test('runSelfTest reports an absent gate as a failure, never as a pass', () => {
  // A mount with no selftest is not a green mount — it is one nothing can vouch for.
  const root = mkdtempSync(join(tmpdir(), 'claudinite-nomount-'));
  const r = runSelfTest(root);
  assert.equal(r.ok, false);
  assert.equal(r.ran, false);
  rmSync(root, { recursive: true, force: true });
});

