content.content:
1	// Land a task's delivered pull request under the REPO's delivery settings — the
2	// single home for the auto-merge nuances every PR-delivering task shares. These
3	// helpers were built inside the baselining worker (#455/#565/#649/#677/#690);
4	// they live here because the other `merged-pr` tasks hit the identical failure
5	// shapes (an arm rejected "clean status" on an ungated base stranding a green PR
6	// forever), and two copies of this precedence is exactly the drift the corpus
7	// forbids.
8	//
9	// The contract that keeps tasks simple: a task declares only its outcome CEILING
10	// (`expected_outcome: 'merged-pr'` — it MAY land a PR). Whether the PR actually
11	// lands unreviewed is the MEMBER REPO's call — `maintenance.delivery` in
12	// `.claudinite-checks.json`, where `review` degrades every merged-pr task to
13	// open-pr (member config wins, per-project-scheduling DESIGN §1). Tasks stay
14	// unaware of that setting by construction: they hand their PR to landDelivery()
15	// (directly, or through deliver-generated.mjs) and the repo-shape nuances stay
16	// here:
17	//
18	//   - `review` member          → the PR is opened and LEFT — never armed, never merged.
19	//   - no pull_request CI at all → MERGE directly. GitHub's auto-merge is a queue
20	//     for checks; with nothing to queue behind, the arm is rejected ("Pull
21	//     request is in clean status") every time, and while that rejection was
22	//     swallowed a repo that asked for auto-merge got no merge at all.
23	//   - CI present, but the base branch REQUIRES nothing → the arm is equally
24	//     doomed (same clean-status rejection, #677): skip it, wait for this run's
25	//     own dispatched evidence, and land on it (verify-then-merge).
26	//   - a base gate present — or unreadable, which is never read as absent → ARM,
27	//     with the landing poll as fallback when the arm is rejected (auto-merge
28	//     disabled repo-side, or a pull_request run parked at `action_required`).
29	//
30	// A branch pushed and a PR opened over the Action's GITHUB_TOKEN emit no
31	// pull_request run of their own (GitHub's recursion guard, #565), so
32	// landDelivery also STARTS the PR's checks via workflow_dispatch before deciding
33	// anything — the checks an arm would wait on must exist to conclude.
34	//
35	// The AGENT lane (executor subagents, MCP writes) cannot run this module; its
36	// prose twin is `deliver-pr.md` beside this file, and the two must keep saying
37	// the same thing — a nuance changed here changes there in the same commit.
38	// (baselining's worker consumes this module for the same reason its sibling
39	// tasks do; its family-branch disposal — close-and-recut — stays in the worker,
40	// because no other task re-cuts a per-cycle branch.)
41	
42	const API = 'https://api.github.com';
43	
44	async function gh(token, path, { method = 'GET', body } = {}) {
45	  const res = await fetch(`${API}${path}`, {
46	    method,
47	    headers: {
48	      authorization: `Bearer ${token}`,
49	      accept: 'application/vnd.github+json',
50	      'x-github-api-version': '2022-11-28',
51	      ...(body ? { 'content-type': 'application/json' } : {}),
52	    },
53	    body: body ? JSON.stringify(body) : undefined,
54	  });
55	  let json = null;
56	  try { json = await res.json(); } catch { /* empty body */ }
57	  return { status: res.status, json };
58	}
59	
60	// --- the member's delivery preference ----------------------------------------
61	
62	// The member's delivery preference, normalized. `push`/`auto` → auto-merge and
63	// `pr` → review are the permanent legacy aliases (the maintenance-lane tolerance);
64	// anything else is invalid (null) and fails the run rather than guessing.
65	export function normalizeDelivery(raw) {
66	  const v = String(raw ?? '').trim();
67	  if (v === 'auto-merge' || v === 'auto' || v === 'push') return 'auto-merge';
68	  if (v === 'review' || v === 'pr') return 'review';
69	  return null;
70	}
71	
72	// The default a repo gets when it never declared one.
73	export const DEFAULT_DELIVERY = 'auto-merge';
74	
75	// `maintenance.delivery` is always EXPLICIT — but a key that is simply absent is
76	// DRIFT, not an error. A repo adopted before the key existed, or one whose key
77	// was hand-removed, would otherwise fail its scheduled tasks every night forever
78	// with nothing that could ever fix it (the only writer is check_the_world --init,
79	// which runs once at adoption; baselining's converge is what repairs the drift).
80	// So: resolve to the default and carry on — `materialize: true` tells the one
81	// caller that CAN write the repair (baselining) to do so; everyone else just uses
82	// the resolved value.
83	//
84	// An UNRECOGNIZED value is a different thing entirely: someone wrote an intent
85	// this code cannot honour, and silently substituting a default would deliver
86	// the opposite of what they asked for. That still fails the run (delivery: null).
87	//
88	// Returns { delivery, materialize } — `delivery` null only for the unrecognized
89	// case. A content-free value (empty/whitespace) carries no intent, so it is
90	// treated as absent rather than as a typo.
91	export function resolveDelivery(raw) {
92	  if (raw == null || String(raw).trim() === '') {
93	    return { delivery: DEFAULT_DELIVERY, materialize: true };
94	  }
95	  return { delivery: normalizeDelivery(raw), materialize: false };
96	}
97	
98	// The same resolution, from the raw TEXT of a repo's .claudinite-checks.json —
99	// the shape a caller reading the file off a git blob has in hand. Unparsable or
100	// absent text resolves like a missing key: default, not failure (the file's
101	// integrity is check_the_world's problem, not the delivery step's).
102	export function deliveryFromChecks(text) {
103	  let parsed = null;
104	  try { parsed = JSON.parse(text ?? 'null'); } catch { /* unreadable → absent */ }
105	  return resolveDelivery(parsed?.maintenance?.delivery);
106	}
107	
108	// --- CI dispatch on the delivered PR (#565) -----------------------------------
109	// The GITHUB_TOKEN push/PR-open emits no pull_request run (GitHub's recursion
110	// guard), so the delivery starts the PR's checks itself: dispatch every workflow
111	// that WOULD have run on pull_request and CAN be dispatched.
112	//
113	// "Suppresses" is only half true, and the other half is #455/#205/#95: on some
114	// members GitHub CREATES the pull_request run and parks it at `action_required`
115	// awaiting an approval nobody clicks. The dispatch above still supplies the real
116	// green, but the parked run is what auto-merge refuses over — which is why
117	// arming is not the end of the story and pullDisposition exists.
118	//
119	// Reading the triggers is a best-effort TEXTUAL scan of a workflow's top-level
120	// `on:` block (no YAML parser in the corpus). It covers the shapes workflows
121	// actually use: a block map of trigger keys (with or without nested config), the
122	// inline scalar, and the inline list.
123	export function workflowTriggers(yaml) {
124	  const lines = String(yaml ?? '').split('\n');
125	  const onAt = lines.findIndex((l) => /^(['"]?)on\1\s*:/.test(l));
126	  if (onAt === -1) return [];
127	  const inline = lines[onAt].replace(/^(['"]?)on\1\s*:/, '').replace(/#.*$/, '').trim();
128	  if (inline) return inline.replace(/[[\]]/g, '').split(',').map((s) => s.trim()).filter(Boolean);
129	  const triggers = [];
130	  let childIndent = null;
131	  for (let i = onAt + 1; i < lines.length; i += 1) {
132	    const line = lines[i];
133	    if (!line.trim() || line.trim().startsWith('#')) continue;
134	    const indent = line.length - line.trimStart().length;
135	    if (indent === 0) break;                        // next top-level key — on: is done
136	    childIndent = childIndent ?? indent;            // first child fixes the trigger level
137	    if (indent !== childIndent) continue;           // nested config under a trigger
138	    const m = /^([A-Za-z_]+)\s*:/.exec(line.trim());
139	    if (m) triggers.push(m[1]);
140	  }
141	  return triggers;
142	}
143	
144	// The dispatch plan over the repo's workflow files ({name, content} each):
145	// `dispatch` — runs on pull_request AND carries workflow_dispatch (start these);
146	// `missing`  — runs on pull_request but CANNOT be dispatched (name these in the
147	// log: adding `workflow_dispatch:` to that file's `on:` is the owner's one-line
148	// fix, and silence here would read as "no CI expected" when CI was expected).
149	// A workflow with no pull_request trigger is never touched — dispatchable-but-
150	// unrelated workflows (a release orchestrator, say) must not fire on a delivery.
151	export function ciDispatchPlan(files) {
152	  const dispatch = [];
153	  const missing = [];
154	  for (const { name, content } of files ?? []) {
155	    const triggers = workflowTriggers(content);
156	    if (!triggers.includes('pull_request')) continue;
157	    (triggers.includes('workflow_dispatch') ? dispatch : missing).push(name);
158	  }
159	  return { dispatch, missing };
160	}
161	
162	// The I/O half of the CI dispatch: read the workflow files as they exist ON THE
163	// DELIVERED BRANCH (the delivery may itself have changed them), plan with
164	// ciDispatchPlan, POST a dispatch per selected workflow, and log every outcome —
165	// a silent no-checks PR is exactly the failure mode this exists to close. Needs
166	// the scheduler workflow's `actions: write` (a read-only token 403s the POST
167	// silently — the store-release lesson).
168	// Returns { dispatch, missing, started }: `dispatch`/`missing` are the PLAN
169	// (what the tree says should run), `started` the dispatches GitHub actually
170	// accepted (204). The landing poll must wait only on `started` — a POST that
171	// 403'd (the scheduler workflow missing `actions: write`, the canon's own copy
172	// on 2026-08-08) starts nothing, and counting the plan had the poll waiting for
173	// a run that could never come.
174	export async function dispatchCiRuns({ token, repo, branch, log = console.log }) {
175	  const ref = encodeURIComponent(branch);
176	  const { json: dir } = await gh(token, `/repos/${repo}/contents/.github/workflows?ref=${ref}`);
177	  const files = [];
178	  for (const entry of Array.isArray(dir) ? dir : []) {
179	    if (!/\.ya?ml$/.test(entry.name ?? '')) continue;
180	    const { json } = await gh(token, `/repos/${repo}/contents/.github/workflows/${entry.name}?ref=${ref}`);
181	    files.push({ name: entry.name, content: json?.content ? Buffer.from(json.content, 'base64').toString('utf8') : '' });
182	  }
183	  const { dispatch, missing } = ciDispatchPlan(files);
184	  for (const name of missing) {
185	    log(`${name} runs on pull_request but has no workflow_dispatch trigger — `
186	      + 'cannot start it on the delivered PR; add `workflow_dispatch:` under its `on:` to let the delivery run it');
187	  }
188	  if (!dispatch.length && !missing.length) {
189	    log('no pull_request-triggered workflow — the delivered PR has no checks to wait for');
190	  }
191	  const started = [];
192	  for (const name of dispatch) {
193	    const res = await gh(token, `/repos/${repo}/actions/workflows/${name}/dispatches`, {
194	      method: 'POST', body: { ref: branch },
195	    });
196	    if (res.status === 204) { started.push(name); log(`dispatched ${name} on ${branch} — the delivered PR gets its checks`); }
197	    else {
198	      log(`could not dispatch ${name} on ${branch} (${res.status})`
199	        + (res.status === 403 ? ' — the scheduler workflow needs `actions: write` (a read token 403s this POST silently)' : ''));
200	    }
201	  }
202	  return { dispatch, missing, started };
203	}
204	
205	// --- opening the PR ------------------------------------------------------------
206	
207	// Why the PR-open POST must be status-checked, as a pure predicate: null when
208	// the PR was created, else the message to fail on.
209	//
210	// This is the one call whose silent failure is invisible AND self-perpetuating:
211	// a cycle that pushes its branch but fails to open the PR leaves nothing for the
212	// next cycle to find, branches pile up nightly, and the run still reports `ok`
213	// because nothing read the status. The usual cause is repo-level and invisible
214	// from here — "Allow GitHub Actions to create and approve pull requests" is off
215	// and the POST 403s — so the message names that remedy rather than leaving a
216	// bare status code.
217	export function pullCreateError(status, json) {
218	  if (status === 201 && json?.number) return null;
219	  const detail = json?.message ?? `HTTP ${status}`;
220	  return `${detail} — if this is the Actions PR permission, enable Settings → Actions`
221	    + ' → General → "Allow GitHub Actions to create and approve pull requests"';
222	}
223	
224	// --- the delivery decision -------------------------------------------------------
225	
226	// How an `auto-merge` member's PR actually lands, given whether this repo has any
227	// pull_request-triggered workflow at all.
228	//
229	// GitHub's auto-merge is a QUEUE FOR CHECKS. On a repo with no PR CI there is
230	// nothing to queue behind: the mutation is rejected ("Pull request is in clean
231	// status"), and since the failure was swallowed the PR sat open forever — a repo
232	// that asked for `auto-merge` got no merge at all. Seven of twelve consumers were
233	// in exactly that shape (no `pull_request` trigger anywhere in .github/workflows).
234	//
235	// So: no CI to wait for → MERGE IT, which is what `auto-merge` meant all along.
236	//
237	// `hasPrCi` comes from ciDispatchPlan over the branch's own workflow files —
238	// `dispatch` (startable) plus `missing` (PR-triggered but not dispatchable). Both
239	// empty means no workflow anywhere runs on a pull_request, so no check will ever
240	// appear. That is a fact about the tree, not a race against checks registering.
241	//
242	// `gate` is what the BASE BRANCH requires (classifyMergeGate) — the thing
243	// GitHub's auto-merge actually queues behind. CI existing was the wrong
244	// predicate (#677): on an unprotected base the PR is mergeable the whole time
245	// its checks run, so `enablePullRequestAutoMerge` is rejected "clean status"
246	// every cycle no matter how green — arming there is doomed, and the delivery
247	// goes straight to verify-then-land instead. `unknown` arms: a gate we could
248	// not see is never merged past.
249	export function deliveryAction({ delivery, hasPrCi, gate = 'unknown' }) {
250	  if (delivery !== 'auto-merge') return 'none';
251	  if (!hasPrCi) return 'merge';
252	  return gate === 'absent' ? 'land' : 'arm';
253	}
254	
255	// What the base branch requires before a merge, from the two reads the Action's
256	// GITHUB_TOKEN can make: the branch's `protected` flag and the ruleset rules
257	// that apply to it (deliberately NOT /branches/{base}/protection, which wants
258	// admin). Rule types that queue a PR gate it; rules about pushes and deletions
259	// do not. An unreadable answer is UNKNOWN, never absent — unknown assumes a
260	// gate, so the caller arms rather than merging past a gate it cannot see.
261	const GATING_RULE_TYPES = ['pull_request', 'required_status_checks', 'merge_queue', 'required_deployments'];
262	export function classifyMergeGate({ branchStatus, branchJson, rulesStatus, rulesJson }) {
263	  if (branchStatus !== 200 || typeof branchJson?.protected !== 'boolean') return 'unknown';
264	  if (branchJson.protected) return 'present';
265	  if (rulesStatus !== 200 || !Array.isArray(rulesJson)) return 'unknown';
266	  return rulesJson.some((r) => GATING_RULE_TYPES.includes(r?.type)) ? 'present' : 'absent';
267	}
268	
269	export async function readMergeGate(token, repo, base) {
270	  const branch = await gh(token, `/repos/${repo}/branches/${encodeURIComponent(base)}`);
271	  const rules = await gh(token, `/repos/${repo}/rules/branches/${encodeURIComponent(base)}`);
272	  return classifyMergeGate({
273	    branchStatus: branch.status, branchJson: branch.json,
274	    rulesStatus: rules.status, rulesJson: rules.json,
275	  });
276	}
277	
278	// --- judging a PR by the runs on its head (#455/#205/#95) ---------------------
279	// Arming is best-effort and can fail PERMANENTLY, so "arm and move on" is not a
280	// delivery guarantee. Two shapes, both observed across the fleet, both leaving a
281	// green PR open forever:
282	//
283	//   1. GATED CI. GitHub CREATES the pull_request run for a GITHUB_TOKEN push and
284	//      parks it at conclusion `action_required`, pending a human "Approve and
285	//      run" that nobody is watching for. The run never executes, so it never
286	//      reports; `enablePullRequestAutoMerge` then refuses the PR with "in
287	//      unstable status (required checks are failing)". Meanwhile the
288	//      workflow_dispatch run started on the SAME head sha ran and passed. So CI
289	//      did pass; only the phantom gated run says otherwise.
290	//   2. AUTO-MERGE OFF. The repo never enabled Settings → General → "Allow
291	//      auto-merge", so the mutation is rejected outright no matter how green.
292	//
293	// Both are settled by the same evidence: the runs on the PR's own head sha. If
294	// CI has CONCLUDED and nothing actually failed, the content on that sha is
295	// verified and `auto-merge` means merge it. A gated `action_required` run is not
296	// a failure — it is a run that never happened.
297	//
298	// Deliberately conservative about MERGING, because that bypasses the arm:
299	//   - Anything still queued/running → `wait`. Never merge mid-flight.
300	//   - Any real failure (failure / timed_out / cancelled / startup_failure), or no
301	//     successful run to stand on → `close`: NOT a merge, and equally not a reuse.
302	//     (What `close` means is the CALLER's policy — baselining closes and re-cuts
303	//     its per-cycle branch; a landing pass just leaves the PR standing.)
304	//
305	// A `review` member's PR is the owner's to act on, on their own clock — never
306	// merged, and never closed out from under them either.
307	export const REAL_FAILURES = ['failure', 'timed_out', 'cancelled', 'startup_failure'];
308	
309	export function pullDisposition({ delivery, runs }) {
310	  if (delivery !== 'auto-merge') return 'keep';
311	  const list = (runs ?? []).filter(Boolean);
312	  if (list.some((r) => r.status !== 'completed')) return 'wait';
313	  if (list.some((r) => REAL_FAILURES.includes(r.conclusion))) return 'close';
314	  if (!list.some((r) => r.conclusion === 'success')) return 'close';
315	  return 'merge';
316	}
317	
318	// Why the merge had to happen here rather than through the arm. The log line has
319	// to name which shape this was, or the repo misconfiguration behind it stays
320	// invisible — and it is a REPO setting, so only a human can retire it.
321	export function mergeReason(runs) {
322	  // The no-remedy shape names no setting (#677): on a base that requires
323	  // nothing, landing here IS the design, and sending an owner to fix something
324	  // already correct is worse than saying nothing.
325	  return (runs ?? []).some((r) => r?.conclusion === 'action_required')
326	    ? 'its pull_request run is parked at action_required (never ran) while the dispatched run passed'
327	    + ' — check Settings → Actions → General → workflow-approval requirements'
328	    : 'its dispatched checks concluded green and nothing on the base branch queues an auto-merge';
329	}
330	
331	// Why a PR was left (or closed) rather than merged — the same visibility
332	// argument, for the case that matters more: a member whose CI is genuinely red.
333	export function failureSummary(runs) {
334	  const failed = (runs ?? []).filter((r) => REAL_FAILURES.includes(r?.conclusion));
335	  if (failed.length) return `failing CI: ${failed.map((r) => `${r.name} ${r.conclusion}`).join(', ')}`;
336	  return 'no successful run on its head sha';
337	}
338	
339	// --- landing THIS run's PR when the arm could not (#649) ----------------------
340	// On a member whose pull_request run is gated, EVERY arm fails; deferring to the
341	// next cycle's disposal put a standing ~24h offset between a task's output and
342	// that member's main. The evidence that settles it does not take a day to
343	// arrive: the dispatched run this delivery just started finishes in seconds. So
344	// we wait for it, once, and merge on exactly the reasoning disposal uses. Same
345	// decision, made now.
346	//
347	// Bounded and cheap because it only runs where the arm ALREADY failed (or was
348	// skipped as doomed): a healthy member arms and returns without waiting at all.
349	export const LAND_TIMEOUT_MS = 180_000;
350	export const LAND_POLL_MS = 5_000;
351	
352	// What one poll of the head sha's runs says to do: `merge`, `poll` again, or
353	// `give-up` and leave the PR standing.
354	//
355	// It NEVER closes. A cycle's disposal may close a PR because that PR is LAST
356	// cycle's and this cycle is about to re-cut it; here the PR IS this run's
357	// delivery, and closing it would throw away the work that just ran. A red member
358	// therefore leaves its PR open for the next run (or a human) to dispose of.
359	// `expected` is how many verification runs THIS delivery dispatched on the head
360	// seconds ago. Fewer visible runs than that is the API still registering them —
361	// a POLL, never a verdict. Without it, the first read 0.3s after the dispatch
362	// found an empty list and judged "nothing will ever verify this", stranding
363	// seven members' green PRs in one forced fleet pass (2026-08-07).
364	export function landAttempt({ delivery, runs, expected = 0, elapsedMs = 0, timeoutMs = LAND_TIMEOUT_MS }) {
365	  if ((runs ?? []).length < expected) return elapsedMs >= timeoutMs ? 'give-up' : 'poll';
366	  const disposition = pullDisposition({ delivery, runs });
367	  if (disposition === 'merge') return 'merge';
368	  if (disposition === 'wait') return elapsedMs >= timeoutMs ? 'give-up' : 'poll';
369	  return 'give-up';
370	}
371	
372	// Arm native auto-merge on a PR (by node id) via the GraphQL mutation — the REST
373	// `PUT /merge` would merge NOW, ignoring pending checks; this waits for them.
374	export async function enableAutoMerge(token, pullRequestId) {
375	  const query = 'mutation($id:ID!){enablePullRequestAutoMerge(input:{pullRequestId:$id,mergeMethod:SQUASH}){pullRequest{id}}}';
376	  const res = await fetch(`${API}/graphql`, {
377	    method: 'POST',
378	    headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
379	    body: JSON.stringify({ query, variables: { id: pullRequestId } }),
380	  });
381	  const json = await res.json().catch(() => null);
382	  if (json?.errors?.length) throw new Error(json.errors[0].message);
383	}
384	
385	// Tidy the ref behind a merged (or disposed) PR — a dead branch left on the
386	// remote is litter that accumulates one per run. Never fatal: the branch is not
387	// the deliverable.
388	export async function deleteBranch({ token, repo, ref, log = console.log }) {
389	  if (!ref) return;
390	  const res = await gh(token, `/repos/${repo}/git/refs/heads/${encodeURIComponent(ref)}`, { method: 'DELETE' });
391	  if (res.status !== 204) log(`could not delete branch ${ref} (HTTP ${res.status})`);
392	}
393	
394	const sleep = (ms) => new Promise((resolve) => { setTimeout(resolve, ms); });
395	
396	// The I/O half of same-run landing: poll this PR's head sha until its runs have
397	// concluded, then merge on the same evidence disposal would use a cycle later.
398	// Returns true iff it merged. Best-effort throughout — every failure path leaves
399	// the PR exactly as the arm left it, which is what the next run expects.
400	export async function landNow({ token, repo, pr, delivery, expected = 0, log = console.log }) {
401	  const started = Date.now();
402	  for (;;) {
403	    const { status, json } = await gh(token, `/repos/${repo}/actions/runs?head_sha=${pr.head?.sha ?? ''}&per_page=100`);
404	    if (status !== 200) {
405	      log(`could not read this run's checks for PR #${pr.number} (HTTP ${status}) — leaving it for the next run`);
406	      return false;
407	    }
408	    const runs = (json?.workflow_runs ?? []).map((r) => ({ name: r.name, status: r.status, conclusion: r.conclusion }));
409	    const attempt = landAttempt({ delivery, runs, expected, elapsedMs: Date.now() - started });
410	
411	    if (attempt === 'poll') { await sleep(LAND_POLL_MS); continue; }
412	    if (attempt === 'give-up') {
413	      log(`PR #${pr.number} not landable this run (${failureSummary(runs)})`
414	        + ' — leaving it open for the next run to dispose of');
415	      return false;
416	    }
417	
418	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
419	      method: 'PUT', body: { merge_method: 'squash' },
420	    });
421	    if (res.status === 200) {
422	      log(`merged PR #${pr.number} in-cycle — ${mergeReason(runs)}`);
423	      await deleteBranch({ token, repo, ref: pr.head?.ref, log });
424	      return true;
425	    }
426	    log(`could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`
427	      + ' — leaving it for the next run');
428	    return false;
429	  }
430	}
431	
432	// The whole landing, composed — what a task's delivery calls once its PR exists.
433	// Dispatch the PR's checks (they establish `hasPrCi`, the fact deliveryAction
434	// turns on), read what the base requires, then merge / land / arm per the
435	// decision — with the landing poll as fallback for a failed arm. `pr` must carry
436	// the CURRENT head ({ number, node_id, head: { ref, sha } }): after a force-push,
437	// a stale sha polls runs that will never conclude.
438	//
439	// Returns { merged, action }. `action: 'none'` is the review member — the PR
440	// stands, deliberately, and that is a delivered outcome, not a failure.
441	export async function landDelivery({ token, repo, base, pr, delivery, log = console.log }) {
442	  // Start the PR's checks FIRST — the GITHUB_TOKEN push/open emitted no
443	  // pull_request event, so without this the PR has no runs (#565). AFTER the
444	  // push, so the dispatched runs execute the branch's own head. Best-effort: a
445	  // dispatch failure must not fail the delivery that was already pushed. Run for
446	  // review members too — their owner wants green checks to review against.
447	  const ci = await dispatchCiRuns({ token, repo, branch: pr.head?.ref, log })
448	    .catch((e) => { log(`CI dispatch on ${pr.head?.ref} failed: ${e.message}`); return null; });
449	  const hasPrCi = ci ? ci.dispatch.length + ci.missing.length > 0 : true; // unknown → assume CI, never merge blind
450	  // How many verification runs this delivery ACTUALLY started on the head — what
451	  // the landing poll waits to see registered before it judges anything
452	  // (landAttempt). `started`, never the plan: a rejected dispatch POST starts
453	  // nothing, and waiting on the plan wedges the poll against a run that can
454	  // never come.
455	  const expected = ci?.started?.length ?? 0;
456	
457	  const gate = await readMergeGate(token, repo, base).catch(() => 'unknown');
458	  const action = deliveryAction({ delivery, hasPrCi, gate });
459	  let merged = false;
460	
461	  if (action === 'merge') {
462	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
463	      method: 'PUT', body: { merge_method: 'squash' },
464	    });
465	    if (res.status === 200) { merged = true; log(`merged PR #${pr.number} directly — this repo has no pull_request CI to gate on`); }
466	    else log(`could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`);
467	  } else if (action === 'land') {
468	    // The base requires nothing, so auto-merge has no queue to wait behind and
469	    // the arm mutation would be rejected "clean status" — every run, no setting
470	    // to fix (#677). Skip the doomed arm; wait for this run's own dispatched
471	    // evidence and land on it. Delivery must land every cycle, not heal next cycle.
472	    log(`${base} requires nothing to merge — skipping the doomed auto-merge arm;`
473	      + ` waiting for this run's ${expected} dispatched run(s) and landing PR #${pr.number} here`);
474	    merged = await landNow({ token, repo, pr, delivery, expected, log });
475	  } else if (action === 'arm' && pr.node_id) {
476	    // Surfaced, not swallowed: a failed arm is why a delivered PR sits open
477	    // forever, and the two usual causes are both fixable repo settings.
478	    const armed = await enableAutoMerge(token, pr.node_id).then(() => true)
479	      .catch((e) => {
480	        log(`could not arm auto-merge on PR #${pr.number}: ${e.message}`
481	          + ' — check Settings → General → "Allow auto-merge", and Settings → Actions → General for a'
482	          + ' workflow-approval requirement parking this PR\'s pull_request run at action_required.'
483	          + ' Waiting for this run\'s dispatched checks and landing it here.');
484	        return false;
485	      });
486	    // Only where the arm failed. A member that armed is GitHub's to land, and
487	    // waiting on it here would add a poll to every healthy repo for nothing.
488	    if (!armed) merged = await landNow({ token, repo, pr, delivery, expected, log });
489	  }
490	  return { merged, action };
491	}
492

