content.content:
1	// WHICH MECHANISM SERVES THIS REPO — the skew guard for the rollout (#768's first
2	// risk). In the ENGINE, not in the canon-internal `updates/` tree, because both
3	// sides must read one definition and one of them is VENDORED: baselining's worker
4	// runs from a member's own mount, so a guard it could not import would be a guard
5	// only half the system obeys — which is worse than none. While baselining and the update flows both exist, a repo must be served by
6	// exactly ONE of them: two mechanisms converging one mount would race on the same
7	// files, and the loser's write would look like drift the winner then "repairs",
8	// nightly, forever.
9	//
10	// The answer is a per-repo flag, because the transition is per-repo by construction:
11	// a member moves when the update that migrates it says so, not when the canon does.
12	//
13	// DEFAULT IS THE STATUS QUO. A repo that says nothing is served by baselining —
14	// which is what every member is doing today, so a member that never hears about any
15	// of this keeps working unchanged. That is the one direction a default may point:
16	// toward what is already true, never toward the new thing.
17	//
18	// …but the default is a READING, not a policy. The corpus's rule is that automation
19	// maintains the explicit value in every file it maintains, so the flag sits visibly
20	// in the exact file anyone would go to change it, and a missing key becomes drift the
21	// automation repairs rather than a case code must interpret forever. `servedBy`
22	// therefore reports whether the value was DECLARED or inferred: the flip is the
23	// update's own write, and the inferred case is what tells it there is a write owed.
24	export const MECHANISMS = ['baselining', 'updates'];
25	export const DEFAULT_MECHANISM = 'baselining';
26	
27	// The declaration key. Beside `delivery`, because both answer "how is this repo
28	// maintained" and a second home for the same question is how a repo ends up
29	// answering it twice, differently.
30	export const MAINTENANCE = 'maintenance';
31	export const MECHANISM_KEY = 'mechanism';
32	
33	// `{ mechanism, declared }` — the mechanism to run, and whether the repo actually
34	// said so. An unrecognised value is NOT silently treated as the default: it is the
35	// one case where guessing could hand a repo to the wrong mechanism, so it reports
36	// itself as undeclared with the offending value attached, and a caller that cares
37	// stops rather than picking.
38	export function servedBy(declaration) {
39	  const raw = declaration?.[MAINTENANCE]?.[MECHANISM_KEY];
40	  if (raw === undefined || raw === null) return { mechanism: DEFAULT_MECHANISM, declared: false };
41	  if (typeof raw !== 'string' || !MECHANISMS.includes(raw)) {
42	    return { mechanism: DEFAULT_MECHANISM, declared: false, invalid: raw };
43	  }
44	  return { mechanism: raw, declared: true };
45	}
46	
47	// The two questions the mechanisms ask about themselves, so neither has to know the
48	// other's name at its call site — and so the "exactly one" property is one
49	// expression rather than two that can disagree.
50	export const servedByUpdates = (declaration) => servedBy(declaration).mechanism === 'updates';
51	export const servedByBaselining = (declaration) => servedBy(declaration).mechanism === 'baselining';
52	
53	// The declaration a flip writes: the mechanism made explicit, everything else
54	// untouched. Returned rather than written, so the caller that owns the file owns the
55	// write — and so this stays testable without one.
56	export function withMechanism(declaration, mechanism) {
57	  if (!MECHANISMS.includes(mechanism)) throw new Error(`unknown mechanism "${mechanism}" — one of ${MECHANISMS.join(', ')}`);
58	  const base = declaration && typeof declaration === 'object' && !Array.isArray(declaration) ? declaration : {};
59	  return { ...base, [MAINTENANCE]: { ...(base[MAINTENANCE] ?? {}), [MECHANISM_KEY]: mechanism } };
60	}
61

