// A migration record MAY carry a machine-readable AGENTIC note (task-prework
// DESIGN §7, the primitive absorbed from #405): member-side adaptation that no
// script can do — adapting consumer-authored `local/packs/` content to a changed
// engine contract. Shape: `agentic: { model, instructions }`, model a non-`none`
// family. baselining's prework reads this to decide whether a pending note
// needs the agent STAGE (and must therefore hold the stamp) rather than converging
// in code. Returns the validated note, or null when the record carries none;
// throws on a malformed note so a typo fails loudly instead of silently skipping
// agentic work (the #405 correctness risk).
export function migrationAgentic(m) {
  const a = m.agentic;
  if (a === undefined || a === null) return null;
  // NO AGENTIC WORK ON AN ENGINE MIGRATION, EVER (DESIGN §5, owner decision 3). The
  // engine update flow has no agentic stage and no lane to add one, so a note on an
  // engine record is not work that gets done later — it is a record that stops the
  // flow for every repo whose gap contains it. Rejected here, at the registry, so it
  // cannot be written in the first place; a pack record is where such work belongs,
  // as its update's apply stage.
  //
  // Judged by WHERE THE RECORD LIVES (`dir`, corpus-relative), the same structural
  // classifier everything else in this scheme uses. A spec with no `dir` is a caller
  // testing the shape rather than a discovered record, and is left alone.
  if (typeof m.dir === 'string' && m.dir.startsWith('engine/')) {
    throw new Error(`migration ${m.id}: an ENGINE migration may not carry an "agentic" note — `
      + 'the engine flow cannot run one (DESIGN §5). Move the work to the owning pack\'s apply stage.');
  }
  if (typeof a !== 'object' || Array.isArray(a)) {
    throw new Error(`migration ${m.id}: "agentic" must be an object { model, instructions }`);
  }
  if (!MODEL_FAMILIES.includes(a.model) || a.model === 'none') {
    throw new Error(`migration ${m.id}: agentic.model must be a non-"none" model family (${MODEL_FAMILIES.filter((f) => f !== 'none').join(', ')})`);
  }
  if (typeof a.instructions !== 'string' || a.instructions.trim() === '') {
    throw new Error(`migration ${m.id}: agentic.instructions must be a non-empty string`);
  }
  return { model: a.model, instructions: a.instructions };
}

// The records that carry a valid agentic note — the pending set baselining must
// escalate to an agent rather than apply in code. Stamp-date filtering (which
// notes still apply) is the caller's; this is the agentic gate over that set.
export function agenticMigrations(migrations) {
  return migrations.filter((m) => migrationAgentic(m) !== null);
}

// The 2026-08-11 fleet-baseline conversion (#749): the sheepdog pack's manual lever
// over the fleet stopped being a standalone WORKFLOW (a managed copy in the enforcer's
// own .github/, the one file the nightly converge could never push — #649) and became
// an ordinary `manual`-frequency TASK (packs/sheepdog/tasks/fleet-baseline/) riding
// the vendored scheduler: Actions → Claudinite scheduler → Run workflow →
// `overrides: FORCE_TASKS=fleet-baseline`.
//
// Canon-side the conversion is complete — the stub the old record materialized
// (packs/sheepdog/stubs/workflows/fleet-baseline.yml) is deleted, which makes the
// 2026-08-05 sheepdog-fleet-baseline record's materialization a permanent no-op (a
// missing template is a skip, never a clobber; see applyMaterializations). What
// remains member-side is the COPY that record installed: an enforcer's own
// .github/workflows/fleet-baseline.yml, now orphaned — its `run:` step points at a
// mount path the vendor refresh no longer carries, so left in place it is a button
// that fails when pressed. Removing a workflow file needs the `workflows` permission
// the Action token does not hold, so the removal rides baselining's agent stage over
// MCP — the same lane that landed the file (#649), run in reverse.
const DECLARATION = '.claudinite-checks.json';
const PACK = 'sheepdog';

export default {
  id: 'fleet-baseline-task',
  landed: '2026-08-11',
  version: 1,
  summary: 'fleet-baseline converted from a standalone workflow to a manual-frequency sheepdog task; the enforcer\'s .github/workflows/fleet-baseline.yml copy is retired',

  // Same gate as the record that installed the file: does this repo declare the
  // sheepdog pack. An unreadable declaration means "not an enforcer as far as this
  // record can tell" — skip, never guess.
  appliesTo: async (read) => {
    const text = await read(DECLARATION);
    if (!text) return false;
    let cfg;
    try { cfg = JSON.parse(text); } catch { return false; }
    return (Array.isArray(cfg?.packs) ? cfg.packs : [])
      .some((e) => (typeof e === 'string' ? e : e?.id) === PACK);
  },

  agentic: {
    model: 'haiku',
    instructions: 'If this repo has a tracked .github/workflows/fleet-baseline.yml, delete it (git rm) on the maintenance branch — the fleet-baseline lever is now the sheepdog pack\'s manual-frequency task (run the Claudinite scheduler workflow by hand with overrides FORCE_TASKS=fleet-baseline), and the old workflow points at mount paths the vendor refresh no longer carries, so it is a button that fails when pressed. Do not touch claudinite-scheduler.yml. A repo with no such file needs nothing.',
  },

  legacyPresent: async (exists) => exists('.github/workflows/fleet-baseline.yml'),
};

