1	import { copyFileSync, mkdirSync, rmSync, renameSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
2	import { join, dirname } from 'node:path';
3	import { fileURLToPath } from 'node:url';
4	import { computeVendorSet, SHARED_SUBDIR } from '../vendoring/compute-vendor-set.mjs';
5	import { loadPacks, resolveDeclaredPacks, packEntryId } from '../engine/pack_loader/pack-registry.mjs';
6	import { ENGINE_VERSION } from '../engine/version.mjs';
7	import { migrationDirs, migrationApplies, flowOf, DECLARATION_FILE } from '../engine/checks/helpers/active-migrations.mjs';
8	import { loadMigrations, applyMigration } from '../engine/migrations/registry.mjs';
9	import { NEEDS_HUMAN, runSelfTest, deliveryDecision } from './engine-update.mjs';
10	
11	// THE PACK UPDATE FLOW (docs/versioned-updates/DESIGN.md §3): move one repo's
12	// declared packs from the versions it has installed to the ones this canon ships.
13	// The same shape as the engine flow beside it — vendor, migrate, converge, stamp,
14	// gate — with three deliberate differences, each a consequence of what a pack IS:
15	//
16	//   1. IT WRITES `.github/workflows/`. The scheduler workflow's content is a
17	//      function of the TASK SET (`declaredSecrets` unions the required secrets of
18	//      every discovered task), so pack changes are what rewrite it — and this flow
19	//      is the one that carries a credential able to land it (owner decision 2).
20	//      That is what retires the withholding pattern: nothing is silently dropped
21	//      from a push here.
22	//   2. IT ENFORCES `minEngineVersion`. A pack version declares the lowest engine it
23	//      runs on; applying it past that is a guess, and a guess about whether a
24	//      member's engine can load a pack is how a fleet goes quiet. Violation is a
25	//      terminal, never a downgrade to "try anyway".
26	//   3. IT HAS AN AGENTIC TAIL — the one place agentic work survives, because the
27	//      pack's new rules meet member-authored content the canon has never seen. This
28	//      module is the DETERMINISTIC half and ends by saying whether that stage is
29	//      needed; the stage itself belongs to the shell that can dispatch a session.
30	//
31	// Everything else is shared with the engine flow on purpose: the same version
32	// predicate decides the gap, the same self-test gates the merge, and every
33	// non-green end is the same `needs-human` terminal (DESIGN §5).
34	const canonRoot = dirname(dirname(fileURLToPath(import.meta.url))); // <canon>/updates/
35	
36	// A pack's own half of the vendor set: its directory, and nothing else. The engine
37	// tree and the catalog belong to the engine flow, which is what keeps two flows
38	// converging one mount from ever fighting over a file.
39	export const isPackFile = (rel, id) => rel.startsWith(`packs/${id}/`);
40	
41	// The records this repo still needs for one pack, oldest first — the same predicate
42	// the engine flow ranges over, with that pack's number instead of the engine's.
43	export function packRecordsInGap(id, installed, { today } = {}) {
44	  return migrationDirs().filter((d) => {
45	    const of = flowOf(d);
46	    return of.flow === 'pack' && of.pack === id && migrationApplies(d, { installed, today });
47	  });
48	}
49	
50	// What a pack update would do to each declared pack, judged before anything is
51	// written: its installed version, the version this canon ships, whether the repo's
52	// engine satisfies the pack's minimum, and the records in between.
53	//
54	// `blocked` is the whole point of returning this rather than a boolean. A pack the
55	// engine is too old for is not skipped quietly and not applied hopefully — it is
56	// named, with both numbers, because the fix (update the engine first) is a sentence
57	// long and unguessable from a silent no-op.
58	export function planPackUpdates(packs, declared, installed, { today, engineVersion = ENGINE_VERSION } = {}) {
59	  const byId = new Map(packs.map((p) => [p.id, p]));
60	  const plan = [];
61	  for (const entry of resolveDeclaredPacks(declared ?? [], packs)) {
62	    const id = packEntryId(entry);
63	    const pack = id === undefined ? undefined : byId.get(id);
64	    if (!pack || plan.some((p) => p.id === id)) continue;      // a local pack, or already planned
65	    const from = installed?.packVersions?.[id];
66	    const to = pack.version;
67	    const needs = pack.minEngineVersion;
68	    const blocked = typeof needs === 'number' && needs > engineVersion
69	      ? `pack "${id}" version ${to} needs engine ${needs}; this repo runs engine ${engineVersion}`
70	      : null;
71	    plan.push({
72	      id,
73	      from: typeof from === 'number' ? from : null,
74	      to: typeof to === 'number' ? to : null,
75	      blocked,
76	      records: packRecordsInGap(id, installed, { today }),
77	    });
78	  }
79	  return plan;
80	}
81	
82	const outcome = (status, detail, extra = {}) => ({ status, detail, ...extra });
83	
84	// Update `targetRoot`'s declared packs to the versions this canon ships. Same
