1	import { join, dirname } from 'node:path';
2	import { fileURLToPath, pathToFileURL } from 'node:url';
3	import { MIGRATION_FILE, migrationDirs, migrationActive, recordName } from '../checks/helpers/active-migrations.mjs';
4	import { MODEL_FAMILIES } from '../scheduler/model-map.mjs';
5	
6	// <corpus>/engine/migrations/ — records are addressed corpus-relative, because they
7	// no longer share one directory with this module: an engine record sits beside it,
8	// a pack's under that pack.
9	const corpusRoot = dirname(dirname(dirname(fileURLToPath(import.meta.url))));
10	
11	// Each migration lives in its own folder under the flow that owns it — an engine
12	// record beside this registry, a pack's under that pack — so a record can carry
13	// assets of its own and each flow can ship exactly its own set. The discovery
14	// surface — the roots, the folder listing, the recency predicate, and
15	// `migrationActive` — lives in the vendored engine lib
16	// (engine/checks/helpers/active-migrations.mjs) because pack CHECKS consult it and packs import
17	// only the engine surface (pack-independence); this registry re-exports it so
18	// canon-side callers keep one import home.
19	export { MIGRATION_FILE, migrationActive, recordName };
20	
21	// Structural discovery, like packs/ and skills/: every
22	// <flow>/migrations/<landed-date>-<slug>/migration.mjs is a spec. ALL records
23	// present load — the apply/backfill path is unconditional, and FETCHING decides
24	// relevance: a vendored consumer mount carries only the recent records
25	// (vendoring's recency window), while a dormant project baselining out of a
26	// fresh canon clone sees every record ever landed and applies what it needs.
27	// Each object carries its `dir` — the record's CORPUS-RELATIVE path, which both
28	// names the record and says which flow owns it.
29	export async function loadMigrations() {
30	  const out = [];
31	  for (const d of migrationDirs()) {
32	    const spec = (await import(pathToFileURL(join(corpusRoot, d, MIGRATION_FILE)).href)).default;
33	    const record = { dir: d, ...spec };
34	    // Validated at LOAD, so a retired field cannot reach a flow that would ignore it.
35	    assertNoAgenticNote(record);
36	    out.push(record);
37	  }
38	  return out;
39	}
40	
41	// Read side — "prefer Y, fall back to X": the ordered list of acceptable paths
42	// for a canonical target (canonical first, then its legacy aliases). A tolerance
43	// point consults this instead of hardcoding its own LEGACY_* constant, so a
44	// rename is declared once here and every reader picks it up. Unknown targets
45	// resolve to just themselves.
46	export function resolvePath(migrations, canonical) {
47	  for (const m of migrations) {
48	    for (const a of m.aliases ?? []) {
49	      if (a.canonical === canonical) return [a.canonical, ...(a.legacy ?? [])];
50	    }
51	  }
52	  return [canonical];
53	}
54	
55	// Write side — "and rename X -> Y": for each alias whose legacy path still
56	// exists and whose canonical does not, move legacy -> canonical. `exists` and
57	// `move` are injected so the same logic drives a local checkout (sync fs) or a
58	// future API applier (async). Idempotent — a no-op once the rename is done.
59	export async function applyFileAliases(migration, { exists, move }) {
60	  const moved = [];
61	  for (const a of migration.aliases ?? []) {
62	    for (const legacy of a.legacy ?? []) {
63	      if ((await exists(legacy)) && !(await exists(a.canonical))) {
64	        await move(legacy, a.canonical);
65	        moved.push(`${legacy} -> ${a.canonical}`);
66	      }
67	    }
68	  }
69	  return moved;
70	}
71	
72	// Write side — "vendor these pack templates into the repo": for each declared
73	// materialization {template, dest}, copy the canon template to its destination
74	// when the dest is missing or has drifted from the template (idempotent; a
75	// hand-edited copy self-heals on the next pass). `readTemplate` reads from the
76	// canon (the pack tree / mounted .claudinite), `read`/`write` act on the consumer
77	// repo — the source and destination roots differ in a consumer, so they are
78	// distinct injected readers. Gated by the migration's `appliesTo` so it only
79	// touches repos that ship the pipeline (never the canon repo itself).
80	// A materialization whose dest is a WORKFLOW FILE can only be written by a caller that
81	// can get it delivered. The nightly converge pushes with the Action's GITHUB_TOKEN, which
82	// GitHub never lets write under `.github/workflows/`, and the refusal rejects the whole
83	// ref — so writing one into a tree that is about to be pushed by such a caller does not
84	// deliver a workflow, it fails the entire converge and everything else riding it.
85	//
86	// The capable caller announces itself with this variable. The pack update flow sets it
87	// when it can WITHHOLD those paths from its commit and hand them to the apply stage;
88	// anything else — an older vendored worker, a hand-run `node engine/migrations/apply.mjs`, CI —
89	// leaves it unset and the workflow materialization is skipped with a note.
90	//
91	// An ENV HANDSHAKE rather than a probe of the repo on disk, because what matters is what
92	// the RUNNING process can do and the disk cannot answer that: the vendor step earlier in
93	// the same cycle replaces the on-disk worker with the new one while the old code is still
94	// executing.
95	export const WITHHOLD_CAPABLE_ENV = 'CLAUDINITE_CAN_WITHHOLD_WORKFLOWS';
96	const WORKFLOW_DEST = '.github/workflows/';
97	export const callerCanDeliverWorkflows = (env = process.env) => env[WITHHOLD_CAPABLE_ENV] === '1';
98	
99	export async function applyMaterializations(migration, { readTemplate, read, write, env = process.env }) {
100	  if (!migration.materialize?.length) return [];
101	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
102	  const done = [];
103	  for (const { template, dest } of migration.materialize) {
104	    const content = await readTemplate(template);
105	    if (content == null) continue; // template missing (partial mount) — skip, never clobber with nothing
106	    if ((await read(dest)) === content) continue; // already vendored, unchanged
107	    if (dest.startsWith(WORKFLOW_DEST) && !callerCanDeliverWorkflows(env)) {
108	      // Reported rather than silent — a silent skip reads as "already current". A caller
109	      // that can withhold writes it on a later cycle.
110	      done.push(`SKIPPED ${dest} (workflow file; this caller cannot deliver one)`);
111	      continue;
112	    }
113	    await write(dest, content);
114	    done.push(`${dest} <- ${template}`);
115	  }
116	  return done;
117	}
118	
119	// Write side — "rewrite these refs in place": for each declared file, apply its
120	// replacements (only those still matching), writing back when anything changed.
121	// Idempotent — a no-op once nothing matches. Preserves the rest of the file, so
122	// per-repo tweaks the template can't carry (e.g. an uncommented build_env block)
123	// survive. Same `appliesTo` gate.
124	//
125	// A replacement is either LITERAL (`{ from, to }`) or a PATTERN
126	// (`{ pattern: /…/g, to }`) — the regex-first shape engine migrations are meant to
127	// take (DESIGN §2.3), for the changes where no literal is common across repos.
128	// The pattern must be global, because every replacement here means replace-ALL:
129	// a non-global regex would silently rewrite only the first occurrence and leave a
130	// half-migrated file that reads as migrated.
131	export async function applyRewrites(migration, { read, write }) {
132	  if (!migration.rewrite?.length) return [];
133	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
134	  const done = [];
135	  for (const { file, replace } of migration.rewrite) {
136	    const text = await read(file);
137	    if (text == null) continue;
138	    let next = text;
139	    for (const r of replace ?? []) {
140	      if (r.pattern !== undefined) {
141	        if (!(r.pattern instanceof RegExp) || !r.pattern.global) {
142	          throw new Error(`migration ${migration.id}: rewrite pattern for ${file} must be a global RegExp — a non-global one rewrites only the first match`);
143	        }
144	        next = next.replace(r.pattern, r.to);
145	      } else {
146	        next = next.split(r.from).join(r.to);
147	      }
148	    }
149	    if (next !== text) { await write(file, next); done.push(file); }
150	  }
151	  return done;
152	}
153	
154	// The declaration a pack-seeding op writes into. Fixed, not a parameter: this op
155	// declares PACKS, and a repo's declaration lives in exactly one file. A `file` knob
156	// would quietly make it a general JSON editor, which is a much larger thing to own.
157	export const DECLARATION = '.claudinite-checks.json';
158	
159	// Write side — "every member should now declare this pack": for each declared
160	// `{ id, config }`, add that pack to the member's `packs` when it is absent, and
161	// fill in a `config` the entry does not already carry. The op the other three could
162	// not express — `materialize` writes a whole template (it would clobber a per-repo
163	// declaration) and `rewrite` replaces literal text (declarations share no literal
164	// across repos) — and the shape a fleet-wide capability change actually has: a pack
165	// every member should run, whose parameters the canon knows and the member cannot
166	// derive.
167	//
168	// SEEDING, NEVER OVERRIDING. A pack the repo already declares keeps its entry, and a
169	// config it already carries is left exactly as it is: both are that repo's decisions,
170	// and a migration that reasserted them would fight the project every night. That
171	// makes the op idempotent by construction — a no-op once the entry is there.
172	//
173	// ORDER MATTERS AROUND IT. Declaring a pack whose code is not in the member's mount
174	// is a blocking `config` error there, so the caller must re-converge the mount after
175	// applying (baselining does; see its worker). This module only writes the file.
176	//
177	// It round-trips the file through JSON rather than editing settings as text, so the
178	// result is canonical 2-space settings with a trailing newline (what `--init` writes,
179	// and what every fleet declaration already is). Malformed JSON is left alone: the
180	// world runner reports it as the settings error it is, and a migration is not the
181	// place to guess at a repair. Same `appliesTo` gate as the other write ops.
182	export async function applyPackDeclarations(migration, { read, write }) {
183	  if (!migration.declarePacks?.length) return [];
184	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
185	  const raw = await read(DECLARATION);
186	  if (raw == null) return [];                       // not a member — nothing to declare into
187	  let config;
188	  try { config = JSON.parse(raw); } catch { return []; }
189	  if (config === null || typeof config !== 'object' || Array.isArray(config)) return [];
190	  const packs = Array.isArray(config.packs) ? [...config.packs] : [];
191	  const idOf = (e) => (typeof e === 'string' ? e : e?.id);
192	  const done = [];
