216	// own disk. `local_packs/<id>` → `local/<id>` is a pure pattern, but a BARE id is
217	// only a local pack if that repo has one by that name — and a bare id that names a
218	// canon pack must not be touched. No regex can tell those apart, so the record
219	// declares `normalizeLocalDeclarations: true` and the deterministic code ships with
220	// the engine (DESIGN §2.3's "rarely code"). It is one op with one meaning, not a
221	// general escape hatch for arbitrary code in a record.
222	//
223	// SEEDS NOTHING AND DROPS NOTHING: entry objects keep their config, answers and
224	// order; only the id token changes. Idempotent — a repo already on `local/` is a
225	// no-op — and it patches the parsed declaration back through JSON.stringify with
226	// the same 2-space shape every other declaration writer here uses.
227	export async function applyLocalDeclarationNormalization(migration, { read, write, exists }) {
228	  if (!migration.normalizeLocalDeclarations) return [];
229	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
230	  const raw = await read(DECLARATION);
231	  if (raw == null) return [];
