238	  const packs = [];
239	  for (const entry of config.packs) {
240	    const id = typeof entry === 'string' ? entry : entry?.id;
241	    if (typeof id !== 'string' || id.startsWith(LOCAL_DECL)) { packs.push(entry); continue; }
242	    let bare = id.startsWith(LEGACY_LOCAL_DECL) ? id.slice(LEGACY_LOCAL_DECL.length) : null;
243	    if (bare === null) {
