245	      // shapes are checked, because a repo mid-relocation may hold either.
246	      const isLocal = (await exists(`.claudinite/local/packs/${id}/pack.mjs`))
247	        || (await exists(`.claudinite/local_packs/${id}/pack.mjs`));
248	      if (!isLocal) { packs.push(entry); continue; }
249	      bare = id;
250	    }
251	    const token = `${LOCAL_DECL}${bare}`;
252	    packs.push(typeof entry === 'string' ? token : { ...entry, id: token });
253	    done.push(`${DECLARATION}: ${id} -> ${token}`);
254	  }
255	  if (done.length) await write(DECLARATION, `${JSON.stringify({ ...config, packs }, null, 2)}\n`);
