259	// The declaration tokens this op normalizes to and from. Stated here rather than
260	// imported from the pack registry: this module is the write side a consumer runs
261	// out of its own mount, and the two prefixes are the whole of what it needs.
262	const LOCAL_DECL = 'local/';
263	const LEGACY_LOCAL_DECL = 'local_packs/';
