273	  applied.push(...(await applyMaterializations(migration, io)));
274	  applied.push(...(await applyRewrites(migration, io)));
275	  applied.push(...(await applyPackDeclarations(migration, io)));
276	  applied.push(...(await applyLocalDeclarationNormalization(migration, io)));
277	  return applied;
278	}
279	
280	// THE `agentic` FIELD IS RETIRED (#768 Phase 5). A record used to be able to carry
281	// `agentic: { model, instructions }` — member-side adaptation no script could do —
282	// and baselining's prework read it to decide whether a pending note needed an agent
283	// stage, holding the member's stamp until one ran.
