1	import { readdirSync, existsSync, readFileSync } from 'node:fs';
2	import { join, dirname, basename } from 'node:path';
3	import { fileURLToPath } from 'node:url';
4	
5	// The synchronous migration-registry surface for the CHECK layer. It lives in
6	// the engine lib because pack checks consult it (`migrationActive` gates an
7	// in-flight transition's legacy tolerance) and a pack imports only its own files
8	// and the engine surface (pack-independence). Self-locating relative to the
9	// engine root, so in a vendored consumer — where a mount carries only the recent
10	// vendored records, or none — every query answers from what the mount actually
11	// holds. The full registry (engine/migrations/registry.mjs) builds on this same
12	// surface canon-side.
13	//
14	// TWO HOMES, ONE SHAPE. A record belongs to the flow that owns it: an engine
15	// migration lives at `engine/migrations/<landed-date>-<slug>/`, a pack's at
16	// `packs/<pack>/migrations/<landed-date>-<slug>/`, each with its spec at
17	// migration.mjs (docs/versioned-updates/DESIGN.md §3.7). Discovery walks both,
18	// so a caller never has to know which flow raised a record — and the split is
19	// what lets each flow fetch, and later version-range, only its own.
20	//
21	// All records are equal — there is no active/archived split and no cleanup pass;
22	// FETCHING decides relevance. Vendoring ships only the records landed within
23	// RECENT_WINDOW_DAYS, so an up-to-date consumer carries few-to-none, while a
24	// lagging project updating out of a fresh canon clone sees them all and
25	// applies what it needs.
26	export const MIGRATION_FILE = 'migration.mjs';
27	export const RECENT_WINDOW_DAYS = 7;
28	export const MIGRATIONS_SUBDIR = 'migrations';
29	
30	// <corpus>/engine/checks/helpers/ — the corpus root is this file's fourth parent:
31	// the canon repo root canon-side, the mount root (.claudinite/shared/) in a member.
32	const corpusRoot = dirname(dirname(dirname(dirname(fileURLToPath(import.meta.url)))));
33	
34	const isRecordDir = (name) => /^\d{4}-\d{2}-\d{2}-/.test(name);
35	const subdirs = (dir) => {
36	  try { return readdirSync(dir, { withFileTypes: true }).filter((e) => e.isDirectory()).map((e) => e.name); }
37	  catch { return []; }
38	};
39	
40	// Every directory that may hold records, corpus-relative: the engine's own, and
41	// one per pack present. Derived from the tree rather than a list, so a pack that
42	// grows its first record needs no registration anywhere.
43	export function migrationRoots() {
44	  return [
45	    `engine/${MIGRATIONS_SUBDIR}`,
46	    ...subdirs(join(corpusRoot, 'packs')).sort().map((p) => `packs/${p}/${MIGRATIONS_SUBDIR}`),
47	  ];
48	}
49	
50	// Every migration record present, as CORPUS-RELATIVE paths
51	// (`engine/migrations/2026-08-06-prework-rename`), sorted by landed date so the
52	// set reads chronologically across both homes. Tolerant of absent roots — a
53	// vendored consumer with no recent records, or a pack that has never needed one.
54	export function migrationDirs() {
55	  const found = [];
56	  for (const root of migrationRoots()) {
57	    for (const name of subdirs(join(corpusRoot, root))) {
58	      if (isRecordDir(name) && existsSync(join(corpusRoot, root, name, MIGRATION_FILE))) found.push(`${root}/${name}`);
59	    }
60	  }
61	  // By record name first — the landed-date prefix — so ordering is the canon's
62	  // history, not the alphabet of the directories the records happen to live in.
63	  return found.sort((a, b) => basename(a).localeCompare(basename(b)) || a.localeCompare(b));
64	}
65	
66	// The record folder NAME of a discovered path — what the date prefix and the slug
67	// live on. Callers hold paths; every predicate below judges the name.
68	export const recordName = (dirOrPath) => basename(dirOrPath);
69	
70	const todayIso = () => new Date().toISOString().slice(0, 10);
71	
72	// True while a record folder's landed-date prefix is within the recency window —
73	// the same predicate vendoring uses to decide what ships in a consumer mount,
74	// so "recent enough to tolerate" and "recent enough to vendor" can never drift.
75	// Pure over the folder name (a bare name or a path ending in one), so vendoring
76	// can apply it against its own tree walk.
77	export function recordDirIsRecent(name, today = todayIso()) {
78	  const cutoff = new Date(`${today}T00:00:00Z`).getTime() - RECENT_WINDOW_DAYS * 86400000;
79	  const landedMs = new Date(`${recordName(name).slice(0, 10)}T00:00:00Z`).getTime();
80	  return Number.isFinite(landedMs) && landedMs > cutoff;
81	}
82	
83	// The flow a record belongs to, read off WHERE IT LIVES — the structural
84	// classifier the split already gives us, so no record carries a field saying
85	// which flow it is (and none can carry the wrong one).
86	export function flowOf(dirPath) {
87	  const parts = dirPath.split('/');
88	  if (parts[0] === 'packs' && parts.length > 2) return { flow: 'pack', pack: parts[1] };
89	  return { flow: 'engine' };
90	}
91	
92	// The version a record declares — the version of its owning flow AT WHICH ITS
93	// CHANGE IS IN EFFECT, so a repo below that number has not yet received the
94	// change and still needs the record. A record therefore lands in the same change
95	// as the bump it names (engine/RELEASES.md states the release discipline).
96	//
97	// READ BY REGEX, not by importing the spec, because every caller here is
98	// SYNCHRONOUS — `migrationActive` is called from inside check bodies, and making
99	// it async would ripple through every rule in the corpus. The cost is that the
100	// field must be a plain literal on its own line; the price of that constraint is
101	// paid by one drift-guard test which imports every real record and asserts the
102	// regex agrees with the module (engine-tests/migrations.test.mjs), so the two
103	// readings of the same fact cannot diverge unnoticed.
104	const VERSION_FIELD = /^\s*version:\s*(\d+)\s*,\s*$/m;
105	export function recordVersion(dirPath) {
106	  let src;
107	  try { src = readFileSync(join(corpusRoot, dirPath, MIGRATION_FILE), 'utf8'); } catch { return null; }
108	  const m = VERSION_FIELD.exec(src);
109	  return m ? Number(m[1]) : null;
110	}
111	
112	// The repo the corpus is mounted in: the canon IS its own repo root, while a
113	// member's corpus sits at <repo>/.claudinite/shared. Both roots, one expression —
114	// the shape the corpus insists on for anything that runs in either place.
115	const repoRoot = corpusRoot.endsWith(join('.claudinite', 'shared'))
116	  ? dirname(dirname(corpusRoot))
117	  : corpusRoot;
118	
119	// The versions this repo has INSTALLED, off its own stamp, or null when it has
120	// none. Null is a real answer and not a zero: a repo that has never converged
121	// under the versioned scheme (and the canon, which is not a member and carries no
122	// stamp) is *unknown*, which the predicate below answers by date instead of by
123	// pretending the repo is at version 0.
124	export function installedVersions(read = () => { try { return readFileSync(join(repoRoot, DECLARATION_FILE), 'utf8'); } catch { return null; } }) {
125	  const raw = read();
126	  if (raw == null) return null;
127	  let parsed;
128	  try { parsed = JSON.parse(raw); } catch { return null; }
129	  const stamp = parsed?.claudinite;
130	  if (!stamp || typeof stamp !== 'object') return null;
131	  const { engineVersion = null, packVersions = null } = stamp;
132	  if (engineVersion === null && packVersions === null) return null;
133	  return { engineVersion, packVersions: packVersions ?? {} };
134	}
135	export const DECLARATION_FILE = '.claudinite-checks.json';
136	
137	// What this repo has installed of the flow that owns `dirPath` — undefined when
138	// the stamp says nothing about that flow (an unversioned pack, a stamp predating
139	// the scheme). Kept distinct from a real number all the way down.
140	export function installedFor(dirPath, installed) {
141	  if (!installed) return undefined;
142	  const of = flowOf(dirPath);
143	  const v = of.flow === 'engine' ? installed.engineVersion : installed.packVersions?.[of.pack];
144	  return typeof v === 'number' ? v : undefined;
145	}
146	
147	// THE ONE PREDICATE: does this record still apply to a repo in this state?
148	//
149	// Version-ranged when both numbers are known — a record applies exactly while the
150	// repo sits BELOW the version its change took effect at, so an up-to-date repo
151	// matches none and a lagging one matches exactly its gap. That is what vendoring
152	// fetches by and what check-tolerance tolerates by, one function, so "shipped to
153	// the mount" and "tolerated by a check" can never mean different things.
154	//
155	// Falls back to the landed-date window when either number is unknown: a repo that
156	// has not converged since versions existed, and the canon itself, which carries no
157	// stamp and is nobody's member. Unknown is answered as unknown — never as zero,
158	// which would make every record apply to everything, forever.
159	export function migrationApplies(dirPath, { installed = null, today = todayIso() } = {}) {
160	  const have = installedFor(dirPath, installed);
161	  const want = recordVersion(dirPath);
162	  if (have === undefined || want === null) return recordDirIsRecent(dirPath, today);
163	  return want > have;
