1	// Fresh-path wiring convergence (task-prework DESIGN §7, the primitive
2	// absorbed from #405). The deterministic half of the self-refresh that
3	// has nothing to do with the vendored mount's CONTENT: the repo-specific wiring a
4	// scheduled Claudinite consumer must carry, converged idempotently in code so the
5	// nightly refresh never needs a model to re-enact bootstrap's prose.
6	//
7	// One source of truth: bootstrap Part 5 (the settings hooks) + Part 6 (the
8	// scheduler workflow) describe this same set for a fresh adoption; this module is
9	// what both bootstrap and the update flows CALL, so the wiring can never drift between
10	// "how a repo is set up" and "how the nightly keeps it set up".
11	//
12	// Operates on a repo working tree at `root` with node:fs directly (like
13	// apply-vendor-set.mjs), returning a summary of what it changed — idempotent: a
14	// repo already converged produces an empty change list.
15	
16	import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
17	import { join, dirname, relative } from 'node:path';
18	import { pathToFileURL } from 'node:url';
19	import { hashedCron } from './hash-minute.mjs';
20	
21	// The settings-hook registrations a scheduled repo carries (bootstrap Part 5).
22	// Ensured present without clobbering — a set-union keyed on the command string, so
23	// a repo's own extra hooks and any hand-added entries survive untouched.
24	export const REQUIRED_HOOKS = [
25	  { event: 'SessionStart', matcher: null, command: 'bash $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/session-start-command.sh' },
26	  { event: 'Stop', matcher: null, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/stop-command.mjs' },
27	  { event: 'PreToolUse', matcher: 'Bash', command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/pretooluse-command.mjs' },
28	  { event: 'SessionEnd', matcher: null, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/session-end-command.mjs' },
29	];
30	
31	export const SCHEDULER_WORKFLOW = '.github/workflows/claudinite-scheduler.yml';
32	export const SETTINGS_PATH = '.claude/settings.json';
33	export const CLAUDE_MD = 'CLAUDE.md';
34	export const README = 'README.md';
35	
36	// The pack-badge row: the marks of the packs this repo declares, on a single
37	// line of its README. Adoption seeds it and the repo owns it from there — which
38	// is why the row is gated behind `{ badges: true }` (the CLI's `--badges`, passed
39	// by bootstrap alone) rather than converged like the surfaces around it. A
40	// README belongs to its repo: a nightly that re-derived this row would rewrite a
41	// member's README every time its declaration moved, so the nightly stays out and
42	// a stale row is the repo's to fix (re-run the converge with `--badges`).
43	//
44	// Delimited by HTML comments rather than located by position, so the row can be
45	// re-converged in place wherever the repo has moved it, and so anything the repo
46	// writes AFTER the closing marker on the same line (a tagline, a build badge) is
47	// its own and survives untouched — which is why the CLOSING marker stays inline,
48	// at the end of the badges' own line.
49	//
50	// The OPENING marker gets a line to itself, and that newline is load-bearing: a
51	// line that BEGINS with `<!--` opens a CommonMark HTML block, and every character
52	// through the line carrying `-->` is then emitted as raw HTML. Put the badges
53	// after the opening marker on one line and a README renders the literal text
54	// `![basics](…)` instead of the images (#587). Breaking the line ends the HTML
55	// block at the marker, so the badges start a paragraph and parse as markdown.
56	export const BADGE_ROW_START = '<!-- claudinite:packs -->';
57	export const BADGE_ROW_END = '<!-- /claudinite:packs -->';
58	const BADGE_ROW_RE = new RegExp(`${BADGE_ROW_START}[\\s\\S]*?${BADGE_ROW_END}`);
59	
60	// The retired corpus-index import (#385): a line importing `.claudinite/shared/CLAUDE.md`.
61	// The whole line (and its trailing newline) is removed wherever it appears.
62	const CORPUS_IMPORT_RE = /^.*@\.claudinite\/shared\/CLAUDE\.md.*\n?/m;
63	
64	// The project's settings, loaded through the one reader that validates them.
65	// Dynamic and in one place: the scheduler reaches the checks helpers exactly here,
66	// so the cross-tree import stays a single, reviewable edge.
67	const repoConfig = async (root) => (await import('../checks/helpers/repo-context.mjs')).loadConfig(root);
68	
69	// The repo Actions secrets its scheduled tasks declare via `required_secrets`,
70	// deduped and sorted. Async because task discovery is; pure otherwise.
71	export async function declaredSecrets(root, config) {
72	  const { discoverTasks } = await import('./discover.mjs');
73	  const { tasks } = await discoverTasks(root, config);
74	  return [...new Set(tasks.flatMap((t) => t.decl?.required_secrets ?? []))].sort();
75	}
76	
77	// Stamp the declared secrets into the scheduler workflow's engine step, beside
78	// GITHUB_TOKEN. This is the whole delivery mechanism: GitHub Actions requires each
79	// secret to be named statically in the workflow, and a task's `required_secrets` is
80	// exactly that list — so the wiring converge writes it, and a worker then reads
81	// `process.env.<NAME>` like any other environment variable. No bundle, no parsing,
82	// no engine-side selection. Regenerated from the stub each converge, so the list
83	// tracks the declarations rather than accumulating.
84	export function withDeclaredSecrets(stubText, names = []) {
85	  if (!names.length) return stubText;
86	  const lines = names.map((n) => `          ${n}: \${{ secrets.${n} }}`).join('\n');
87	  return stubText.replace(/^(\s*GITHUB_TOKEN: \$\{\{ github\.token \}\})$/m, `$1\n${lines}`);
88	}
89	
90	// Re-converge the scheduler workflow to the vendored stub, with the cron minute set
91	// to this repo's stable hashed value (never guessed — hash-minute.mjs, a pure
92	// function of the full name, so re-vendors and this convergence agree) and the
93	// declared `required_secrets` stamped into the engine step's env. `stubText` is the
94	// vendored stub's content (the caller reads it from the mount). Returns true when
95	// the file was written (absent, or drifted from the target).
96	export function convergeSchedulerWorkflow(root, fullName, stubText, secretNames = []) {
97	  const target = withDeclaredSecrets(stubText, secretNames)
98	    .replace(/cron:\s*'[^']*'/, `cron: '${hashedCron(fullName)}'`);
99	  const path = join(root, SCHEDULER_WORKFLOW);
100	  const current = existsSync(path) ? readFileSync(path, 'utf8') : null;
101	  if (current === target) return false;
102	  mkdirSync(dirname(path), { recursive: true });
103	  writeFileSync(path, target);
104	  return true;
105	}
106	
107	// Ensure the required settings hooks are present (add-if-missing, never clobber).
108	// Returns { added: [labels], error? }. A malformed settings file is reported, never
109	// overwritten (the transactional stance — surface it, don't destroy hand config).
110	export function ensureHooks(root) {
111	  const path = join(root, SETTINGS_PATH);
112	  let settings = {};
113	  if (existsSync(path)) {
114	    try { settings = JSON.parse(readFileSync(path, 'utf8')); }
115	    catch { return { added: [], error: `${SETTINGS_PATH} is not valid JSON — left untouched` }; }
116	  }
117	  settings.hooks ??= {};
118	  const added = [];
119	  for (const h of REQUIRED_HOOKS) {
120	    const list = (settings.hooks[h.event] ??= []);
121	    const present = list.some((group) =>
122	      (h.matcher == null || group.matcher === h.matcher)
123	      && (group.hooks ?? []).some((entry) => entry?.command === h.command));
124	    if (!present) {
125	      list.push({ ...(h.matcher != null ? { matcher: h.matcher } : {}), hooks: [{ type: 'command', command: h.command }] });
126	      added.push(`${h.event}${h.matcher ? `[${h.matcher}]` : ''}`);
127	    }
128	  }
129	  if (added.length) {
130	    mkdirSync(dirname(path), { recursive: true });
131	    writeFileSync(path, JSON.stringify(settings, null, 2) + '\n');
132	  }
133	  return { added };
134	}
135	
136	// Remove the retired `@.claudinite/shared/CLAUDE.md` corpus-index import (#385) from
137	// the repo's CLAUDE.md. Returns true when a line was removed.
138	export function removeRetiredCorpusImport(root) {
139	  const path = join(root, CLAUDE_MD);
140	  if (!existsSync(path)) return false;
141	  const text = readFileSync(path, 'utf8');
142	  if (!CORPUS_IMPORT_RE.test(text)) return false;
