// THE WITHHOLD, made literal. Everything bound for `.github/workflows/` is
// collected instead of written, so the tree this flow's caller commits can never
// contain a path its token is refused for. Before this, the flow ANNOUNCED the
// capability (see the env below) and had none: the first record materializing a
// workflow would have written it, the worker's `git add -A` would have staged it,
// and the push would have taken the whole cycle down with it.
const withheld = [];
const withhold = (path, content) => {
  const at = withheld.findIndex((w) => w.path === path);
  if (at === -1) withheld.push({ path, content }); else withheld[at] = { path, content };
};
const write = (p, c) => {
  if (p.startsWith(WORKFLOW_DIR)) { withhold(p, c); return; }
  mkdirSync(dirname(join(targetRoot, p)), { recursive: true });
  writeFileSync(join(targetRoot, p), c);
};

