// WHY THE APPLY STAGE IS HERE, in one line — the `reason.detail` the dispatch issue
// renders under "Why the agent is here". Not a brief: the INSTRUCTIONS live in the
// task's own `task.md`, where the executor reads them, and this says only which
// condition fired.
//
// That division is the scheduler's standing rule for the code→agent boundary
// (engine/scheduler/prework.mjs): a request payload carries identifiers and the NAME
// of the condition, "never findings and never instructions — everything else travels
// through the repository." An earlier version of this module shipped a whole rendered
// brief through the payload. Nothing ever read it, which is the only reason the
// duplication stayed invisible: it restated task.md §2–4 from a second home that
// could drift from the first, and it was where a withheld workflow's CONTENT would
// have travelled, out of the PR's diff and out of any human's view.
export function applyStageReason({ packs = [], withheld = [] } = {}) {
  const parts = [];
  if (withheld.length) parts.push(`${withheld.length} withheld workflow file(s) staged under .claudinite/pending-workflows/`);
  if (packs.length) parts.push(`updated rules from: ${packs.join(', ')}`);
  return parts.join('; ') || 'the pack\'s new rules must be applied to content the canon has never seen';
}

